@app.before_request
def _make_session_permanent():
    session.permanent = True
    if 'user_id' in session:
        _skip = ('/', '/api/login', '/api/logout', '/api/register', '/api/banned-contact',
                 '/api/google-login', '/api/verify-code', '/manifest.json',
                 '/pwa-icon-192.png', '/pwa-icon-512.png', '/sw.js', '/site-logo')
        if freq.path not in _skip and not freq.path.startswith('/static'):
            _now = time.time()
            _last_check = session.get('_ban_ts', 0)
            _cached_ban = session.get('_ban', 0)
            if _now - _last_check > 30:
                try:
                    _bc = get_db()
                    _brow = _bc.execute('SELECT banned FROM users WHERE id=?', (session['user_id'],)).fetchone()
                    _bc.close()
                    _cached_ban = int(_brow['banned']) if _brow else 0
                    session['_ban'] = _cached_ban
                    session['_ban_ts'] = _now
                except: pass
            if _cached_ban:
                if freq.path == '/app':
                    pass
                elif freq.path.startswith('/api/'):
                    return jsonify(ok=False, msg='حسابك محظور'), 403
                else:
                    return redirect('/app')

@app.after_request
def gzip_response(response):
    if response.status_code < 200 or response.status_code >= 300:
        return response
    if 'gzip' not in freq.headers.get('Accept-Encoding', '').lower():
        return response
    if response.content_length is not None and response.content_length < 500:
        return response
    ct = response.content_type or ''
    if not any(t in ct for t in ['text/html', 'application/json', 'text/css', 'application/javascript']):
        return response
    data = response.get_data()
    buf = io.BytesIO()
    with gzip.GzipFile(fileobj=buf, mode='wb', compresslevel=6) as f:
        f.write(data)
    response.set_data(buf.getvalue())
    response.headers['Content-Encoding'] = 'gzip'
    response.headers['Content-Length'] = len(response.get_data())
    response.headers['Vary'] = 'Accept-Encoding'
    return response

