BACKUP_DIR = '/root/fc_backups'
BACKUP_INTERVAL = 3600
MAX_BACKUPS = 48

def ensure_backup_dir():
    os.makedirs(BACKUP_DIR, exist_ok=True)

def create_backup(label="auto"):
    ensure_backup_dir()
    ts = datetime.now().strftime("%Y%m%d_%H%M%S")
    backup_name = f"backup_{label}_{ts}"
    backup_folder = os.path.join(BACKUP_DIR, backup_name)
    os.makedirs(backup_folder, exist_ok=True)
    copied = 0
    try:
        files_to_backup = [DB]
        for f in files_to_backup:
            if os.path.exists(f):
                shutil.copy2(f, os.path.join(backup_folder, os.path.basename(f)))
                copied += 1
        all_backups = sorted([d for d in os.listdir(BACKUP_DIR) if d.startswith("backup_") and os.path.isdir(os.path.join(BACKUP_DIR, d))])
        while len(all_backups) > MAX_BACKUPS:
            old = all_backups.pop(0)
            shutil.rmtree(os.path.join(BACKUP_DIR, old), ignore_errors=True)
        return backup_name if copied > 0 else None
    except Exception as e:
        pass
    return None

def list_backups():
    ensure_backup_dir()
    backups = []
    for d in sorted(os.listdir(BACKUP_DIR), reverse=True):
        dpath = os.path.join(BACKUP_DIR, d)
        if d.startswith("backup_") and os.path.isdir(dpath):
            files = os.listdir(dpath)
            size = sum(os.path.getsize(os.path.join(dpath, f)) for f in files)
            backups.append({"name": d, "files": len(files), "size": size, "timestamp": os.path.getmtime(dpath)})
    return backups

def restore_backup(backup_name):
    backup_path = os.path.join(BACKUP_DIR, backup_name)
    try:
        if os.path.isdir(backup_path):
            create_backup("pre_restore")
            bak_db = os.path.join(backup_path, os.path.basename(DB))
            if os.path.exists(bak_db):
                shutil.copy2(bak_db, DB)
                return True
    except Exception as e:
        pass
    return False

ensure_backup_dir()
