# ===== مزامنة الخدمات مع المزودين — حذف الخدمات المحذوفة تلقائياً =====
_SYNC_INTERVAL = 600  # كل 10 دقائق
_sync_lock = threading.Lock()
_last_sync_result = {'time': 0, 'removed_svcs': 0, 'removed_cats': 0, 'errors': []}
_MIN_PROVIDER_SERVICES = 20  # أقل عدد خدمات مقبول من مزود (أقل = فشل API)
_MAX_DELETE_RATIO = 0.25  # أقصى نسبة حذف مسموحة بمزامنة واحدة (25%)

def _do_sync_services(force=False):
    """مزامنة service_filters مع API المزودين — حذف الخدمات المحذوفة فقط بشروط أمان"""
    if not _sync_lock.acquire(blocking=False):
        return _last_sync_result
    try:
        provs = get_all_providers()
        active_provs = [p for p in provs if p.get('active') and p.get('api_url') and p.get('api_key')]
        if not active_provs:
            _last_sync_result.update({'time': time.time(), 'removed_svcs': 0, 'removed_cats': 0, 'errors': ['لا يوجد مزودين فعالين']})
            return _last_sync_result

        # 1) جلب خدمات كل مزود
        all_live_svc_ids = set()
        all_live_cat_names = set()
        successful_provs = 0
        failed_provs = 0
        errors = []
        total_live = 0

        for prov in active_provs:
            try:
                r = requests.post(prov['api_url'], data={'key': prov['api_key'], 'action': 'services'}, timeout=25)
                rj = r.json()
                svcs = rj if isinstance(rj, list) else []
                pcount = len(svcs)

                # ⛔ حماية: إذا المزود رجّع أقل من الحد الأدنى — نعتبره فشل API
                if pcount < _MIN_PROVIDER_SERVICES:
                    errors.append(f"⚠️ {prov.get('name','')}: رجّع {pcount} خدمة فقط — تجاوز (قد يكون API معطل)")
                    failed_provs += 1
                    continue

                for s in svcs:
                    all_live_svc_ids.add(str(s.get('service', '')))
                    all_live_cat_names.add(s.get('category', ''))
                total_live += pcount
                successful_provs += 1
            except Exception as e:
                errors.append(f"❌ فشل {prov.get('name','')}: {str(e)[:60]}")
                failed_provs += 1
                continue

        # ⛔ حماية: إذا فشلوا كل المزودين أو ما نجح ولا واحد — لا نحذف شي
        if successful_provs == 0:
            _last_sync_result.update({'time': time.time(), 'removed_svcs': 0, 'removed_cats': 0,
                'errors': errors or ['فشل الاتصال بجميع المزودين — لم يتم حذف شيء']})
            return _last_sync_result

        # ⛔ حماية: إذا في مزود فشل — لا نحذف خدمات لأنها قد تكون مال هذا المزود
        if failed_provs > 0 and not force:
            _last_sync_result.update({'time': time.time(), 'removed_svcs': 0, 'removed_cats': 0,
                'errors': errors + [f'تم إيقاف الحذف التلقائي — {failed_provs} مزود لم يستجب'],
                'live_services': total_live, 'skipped': True})
            return _last_sync_result

        # 2) جلب الفلاتر المخزنة
        conn = get_db()
        frows = conn.execute('SELECT id, filter_type, filter_key, platform FROM service_filters WHERE hidden=0').fetchall()
        total_stored = len(frows)

        if total_stored == 0:
            conn.close()
            _last_sync_result.update({'time': time.time(), 'removed_svcs': 0, 'removed_cats': 0, 'errors': errors, 'live_services': total_live})
            return _last_sync_result

        # 3) تحديد المحذوفات
        to_delete_svcs = []
        to_delete_cats = []
        for f in frows:
            fid = f['id']
            ft = f['filter_type']
            fk = str(f['filter_key'])
            if ft == 'service' and fk not in all_live_svc_ids:
                to_delete_svcs.append(fid)
            elif ft == 'category' and fk not in all_live_cat_names:
                to_delete_cats.append(fid)

        total_to_delete = len(to_delete_svcs) + len(to_delete_cats)

        # ⛔ حماية: لا نحذف أكثر من 25% بمزامنة واحدة (إلا بالمزامنة اليدوية force)
        if not force and total_stored > 0:
            ratio = total_to_delete / total_stored
            if ratio > _MAX_DELETE_RATIO:
                _last_sync_result.update({'time': time.time(), 'removed_svcs': 0, 'removed_cats': 0,
                    'errors': [f'⚠️ المزامنة تريد حذف {total_to_delete} من {total_stored} ({ratio*100:.0f}%) — تجاوز الحد الآمن ({_MAX_DELETE_RATIO*100:.0f}%). استخدم المزامنة اليدوية.'],
                    'live_services': total_live, 'blocked': True, 'would_delete': total_to_delete})
                conn.close()
                return _last_sync_result

        # 4) إخفاء الخدمات المحذوفة من المزودين (بدلاً من الحذف النهائي)
        removed_svcs = len(to_delete_svcs)
        removed_cats = len(to_delete_cats)
        if total_to_delete > 0:
            for fid in to_delete_svcs + to_delete_cats:
                conn.execute('UPDATE service_filters SET hidden=1 WHERE id=?', (fid,))
            conn.commit()
            _bump_svc_version()
            _services_cache['data'] = None
            _services_cache['time'] = 0
            _all_services_cache['data'] = None
            _all_services_cache['time'] = 0

        conn.close()

        result = {
            'time': time.time(), 'removed_svcs': removed_svcs, 'removed_cats': removed_cats,
            'errors': errors, 'total_checked': total_stored, 'live_services': total_live,
        }
        _last_sync_result.update(result)

        if removed_svcs > 0 or removed_cats > 0:
            print(f"🔄 مزامنة: أُخفيت {removed_svcs} خدمة + {removed_cats} فئة (من {total_stored} مخزنة، {total_live} حية)")
            try:
                conn2 = get_db()
                for adm in conn2.execute('SELECT id FROM users WHERE is_admin=1').fetchall():
                    push_user_notif(adm['id'], 'admin', '🔄 مزامنة الخدمات',
                        f'تم إخفاء {removed_svcs} خدمة و {removed_cats} فئة محذوفة من المزودين',
                        'sync')
                conn2.close()
            except: pass

        return result
    except Exception as e:
        _last_sync_result.update({'time': time.time(), 'errors': [str(e)]})
        return _last_sync_result
    finally:
        _sync_lock.release()

def _sync_services_thread():
    time.sleep(300)  # انتظار 5 دقائق بعد بدء السيرفر
    while True:
        try:
            _do_sync_services(force=False)
        except Exception as e:
            print(f"❌ خطأ بمزامنة الخدمات: {e}")
        time.sleep(_SYNC_INTERVAL)

threading.Thread(target=_sync_services_thread, daemon=True).start()
