VAPID_FILE = '/root/fc_vapid.json'
def _get_vapid_keys():
    if os.path.exists(VAPID_FILE):
        with open(VAPID_FILE) as f:
            data = json.load(f)
        if data.get('private') and data.get('public'):
            return data
        os.remove(VAPID_FILE)
    keys = {'private': '', 'public': ''}
    try:
        from py_vapid import Vapid
        v = Vapid()
        v.generate_keys()
        keys = {
            'private': v.private_pem().decode(),
            'public': v.public_key_urlsafe_base64()
        }
    except Exception as e1:
        pass
        try:
            from cryptography.hazmat.primitives.asymmetric import ec
            from cryptography.hazmat.primitives import serialization
            import base64
            private_key = ec.generate_private_key(ec.SECP256R1())
            priv_pem = private_key.private_bytes(
                serialization.Encoding.PEM,
                serialization.PrivateFormat.PKCS8,
                serialization.NoEncryption()
            ).decode()
            pub_bytes = private_key.public_key().public_bytes(
                serialization.Encoding.X962,
                serialization.PublicFormat.UncompressedPoint
            )
            pub_b64 = base64.urlsafe_b64encode(pub_bytes).rstrip(b'=').decode()
            keys = {'private': priv_pem, 'public': pub_b64}
        except Exception as e2:
            pass
    if keys['private'] and keys['public']:
        with open(VAPID_FILE, 'w') as f:
            json.dump(keys, f)
    return keys

VAPID_KEYS = _get_vapid_keys()
PUSH_SUBS_FILE = '/root/fc_push_subs.json'

def _load_push_subs():
    if os.path.exists(PUSH_SUBS_FILE):
        try:
            with open(PUSH_SUBS_FILE) as f:
                return json.load(f)
        except: pass
    return {}

def _save_push_subs(subs):
    with open(PUSH_SUBS_FILE, 'w') as f:
        json.dump(subs, f)

def send_push(user_id, title, body, icon='/pwa-icon-192.png', url='/app'):
    subs = _load_push_subs()
    sub_data = subs.get(str(user_id))
    if not sub_data:
        print(f" [push] skip uid={user_id}: no subscription on server")
        return
    if not VAPID_KEYS.get('private'):
        print(f" [push] skip uid={user_id}: VAPID private key missing")
        return
    sub_list = sub_data if isinstance(sub_data, list) else [sub_data]
    sub_list = [s for s in sub_list if isinstance(s, dict) and s.get('endpoint')]
    if not sub_list:
        print(f" [push] skip uid={user_id}: no valid subscriptions after filter")
        return
    print(f" [push] queuing {len(sub_list)} push(es) for uid={user_id} title={title[:40]!r}")
    for sub in sub_list:
        _executor.submit(_send_push_single, sub, title, body, url, str(user_id))

def _send_push_single(subscription, title, body, url='/app', uid=''):
    if not subscription or not VAPID_KEYS.get('private'):
        return False
    try:
        from pywebpush import webpush
    except ImportError:
        print(" [push] pywebpush NOT INSTALLED — run: pip install pywebpush")
        return False
    push_payload = json.dumps({
        'title': title, 'body': body,
        'icon': '/pwa-icon-192.png', 'url': url,
        'tag': 'fc-' + uuid.uuid4().hex[:12]
    })
    # Primary path: let pywebpush handle VAPID (most reliable)
    try:
        webpush(
            subscription_info=subscription,
            data=push_payload,
            vapid_private_key=VAPID_KEYS['private'],
            vapid_claims={"sub": f"mailto:noreply@{DOMAIN}"}
        )
        print(f" [push] sent uid={uid} title={title[:40]!r}")
        return True
    except Exception as e:
        err = str(e)
        status_code = None
        try:
            if hasattr(e, 'response') and e.response is not None:
                status_code = e.response.status_code
        except: pass
        # Fallback path: manual JWT (in case pywebpush has issues with the key format)
        try:
            import jwt as pyjwt
            from cryptography.hazmat.primitives.serialization import load_pem_private_key
            import base64, urllib.parse
            endpoint = subscription.get('endpoint', '') if isinstance(subscription, dict) else ''
            parsed = urllib.parse.urlparse(endpoint)
            aud = f"{parsed.scheme}://{parsed.netloc}"
            now = int(time.time())
            payload_jwt = {"aud": aud, "exp": now + 43200, "sub": f"mailto:noreply@{DOMAIN}"}
            priv_key = load_pem_private_key(VAPID_KEYS['private'].encode(), password=None)
            token = pyjwt.encode(payload_jwt, priv_key, algorithm="ES256")
            pub_numbers = priv_key.public_key().public_numbers()
            x = pub_numbers.x.to_bytes(32, 'big')
            y = pub_numbers.y.to_bytes(32, 'big')
            pub_b64 = base64.urlsafe_b64encode(bytes([4]) + x + y).rstrip(b'=').decode()
            vapid_headers = {"Authorization": f"vapid t={token},k={pub_b64}"}
            webpush(subscription, push_payload, headers=vapid_headers)
            print(f" [push] sent (JWT fallback) uid={uid} title={title[:40]!r}")
            return True
        except Exception as e2:
            err2 = str(e2)
            try:
                if hasattr(e2, 'response') and e2.response is not None:
                    status_code = e2.response.status_code
            except: pass
            print(f" [push] FAILED uid={uid} status={status_code} primary_err={err[:150]} fallback_err={err2[:150]}")
            # Remove invalid subscriptions (410=Gone, 404=NotFound, 403=Forbidden)
            if status_code in (404, 410, 403) or any(x in err+err2 for x in ['410','Gone','404','NotFound']):
                try:
                    subs = _load_push_subs()
                    if uid in subs:
                        if isinstance(subs[uid], list):
                            subs[uid] = [s for s in subs[uid] if s != subscription]
                            if not subs[uid]: del subs[uid]
                        else:
                            del subs[uid]
                        _save_push_subs(subs)
                        print(f"🗑 [push] removed invalid subscription uid={uid}")
                except Exception as e3:
                    print(f" [push] cleanup error: {e3}")
            return False

