_services_cache = {'data': None, 'time': 0}
_all_services_cache = {'data': None, 'time': 0}
_refresh_lock = threading.Lock()
SERVICES_CACHE_FILE = '/root/fc_services_cache.json'

def _load_services_from_file():
    pass
    try:
        if os.path.exists(SERVICES_CACHE_FILE):
            with open(SERVICES_CACHE_FILE, 'r') as f:
                cached = json.load(f)
            if isinstance(cached.get('data'), list) and len(cached['data']) > 0:
                _services_cache['data'] = cached['data']
                _services_cache['time'] = cached.get('time', 0)
                return True
    except Exception as e:
        pass
    return False

def _save_services_to_file(data):
    pass
    try:
        with open(SERVICES_CACHE_FILE, 'w') as f:
            json.dump({'data': data, 'time': time.time()}, f)
    except Exception as e:
        pass

_load_services_from_file()

def get_smm_services():
    now = time.time()
    api_url, api_key, _pid = get_provider_api()
    if _services_cache['data'] and now - _services_cache['time'] < 60:
        return _services_cache['data']
    if _services_cache['data']:
        def _bg_refresh():
            if not _refresh_lock.acquire(blocking=False):
                return
            try:
                r = requests.post(api_url, data={'key': api_key, 'action': 'services'}, timeout=15)
                data = r.json()
                if isinstance(data, list) and len(data) > 0:
                    old_ids = set(str(s.get('service','')) for s in (_services_cache['data'] or []))
                    new_ids = set(str(s.get('service','')) for s in data)
                    _services_cache['data'] = data
                    _services_cache['time'] = time.time()
                    _save_services_to_file(data)
                    if old_ids != new_ids:
                        _bump_svc_version_only()
            except Exception as e:
                pass
            finally:
                _refresh_lock.release()
        _executor.submit(_bg_refresh)
        return _services_cache['data']
    try:
        r = requests.post(api_url, data={'key': api_key, 'action': 'services'}, timeout=15)
        data = r.json()
        if isinstance(data, list) and len(data) > 0:
            old_ids = set(str(s.get('service','')) for s in (_services_cache['data'] or []))
            new_ids = set(str(s.get('service','')) for s in data)
            _services_cache['data'] = data
            _services_cache['time'] = now
            _save_services_to_file(data)
            if old_ids and old_ids != new_ids:
                _bump_svc_version_only()
            return data
    except Exception as e:
        pass
    return _services_cache['data'] or []

def get_all_smm_services():
    now = time.time()
    if _all_services_cache['data'] is not None and now - _all_services_cache['time'] < 120:
        return _all_services_cache['data']
    all_svcs = []
    try:
        provs = get_all_providers()
        for prov in provs:
            if not prov.get('active'):
                continue
            if not prov.get('show_in_store'):
                continue
            if not prov.get('api_url') or not prov.get('api_key'):
                continue
            svcs = []
            for attempt in range(2):
                try:
                    if prov.get('is_default'):
                        svcs = get_smm_services()
                    else:
                        r = requests.post(prov['api_url'], data={'key': prov['api_key'], 'action': 'services'}, timeout=15)
                        rj = r.json()
                        svcs = rj if isinstance(rj, list) else []
                    if svcs:
                        break
                except:
                    pass
                if attempt == 0:
                    time.sleep(1)
            try:
                for s in svcs:
                    s['_prov_id'] = prov['id']
                all_svcs.extend(svcs)
            except:
                pass
        old_data = _all_services_cache['data']
        old_count = len(old_data) if old_data else 0
        new_count = len(all_svcs)
        if old_count > 20 and new_count < old_count * 0.5:
            _all_services_cache['time'] = now - 90
            return old_data
        old_ids = set((str(s.get('service','')) + ':' + str(s.get('_prov_id',''))) for s in (_all_services_cache['data'] or []))
        new_ids = set((str(s.get('service','')) + ':' + str(s.get('_prov_id',''))) for s in all_svcs)
        _all_services_cache['data'] = all_svcs
        _all_services_cache['time'] = now
        if old_ids != new_ids:
            _bump_svc_version_only()
    except:
        pass
    return _all_services_cache['data'] if _all_services_cache['data'] is not None else []

from flask import g as flask_g

class _ManagedConn:
    """Wrapper: inside request context, close() is a no-op (teardown handles it).
       Outside request context, close() works normally."""
    __slots__ = ('_conn', '_managed')
    def __init__(self, conn, managed=False):
        self._conn = conn
        self._managed = managed
    def __getattr__(self, name):
        return getattr(self._conn, name)
    def close(self):
        if not self._managed:
            self._conn.close()
    def real_close(self):
        self._conn.close()

def get_db():
    """Get DB connection — auto-closes at end of request for route handlers"""
    try:
        if '_db_conn' not in flask_g:
            conn = sqlite3.connect(DB, timeout=30, check_same_thread=False)
            conn.row_factory = sqlite3.Row
            conn.execute('PRAGMA journal_mode=WAL')
            conn.execute('PRAGMA busy_timeout=10000')
            flask_g._db_conn = conn
        return _ManagedConn(flask_g._db_conn, managed=True)
    except RuntimeError:
        conn = sqlite3.connect(DB, timeout=30, check_same_thread=False)
        conn.row_factory = sqlite3.Row
        conn.execute('PRAGMA journal_mode=WAL')
        conn.execute('PRAGMA busy_timeout=10000')
        return _ManagedConn(conn, managed=False)

def get_db_raw():
    pass
    conn = sqlite3.connect(DB, timeout=30, check_same_thread=False)
    conn.row_factory = sqlite3.Row
    conn.execute('PRAGMA journal_mode=WAL')
    conn.execute('PRAGMA busy_timeout=10000')
    return conn

@app.teardown_appcontext
def _close_db(exc):
    conn = flask_g.pop('_db_conn', None)
    if conn is not None:
        try: conn.close()
        except: pass

