@app.route('/pwa-icon-192.png')
@app.route('/pwa-icon-512.png')
def serve_pwa_icon():
    pass
    size = 512 if '512' in freq.path else 192
    custom_path = os.path.join(PWA_ICON_DIR, f'icon-{size}.png')
    if os.path.exists(custom_path):
        resp = make_response(send_file(custom_path, mimetype='image/png'))
        resp.headers['Cache-Control'] = 'public, max-age=3600'
        return resp
    s = size
    r = int(s * 0.22)
    bx = int(s*0.25); by = int(s*0.28); bs = int(s*0.28); br = int(bs*0.25)
    ax1 = bx + int(bs*0.25); ax2 = bx + int(bs*0.75); ay = by + bs//2
    ah = int(bs*0.22)
    sw = max(2, int(s*0.025))
    fs = int(s * 0.35)
    tx = int(s * 0.65)
    ty = int(s * 0.58)
    lsw = max(1, int(s*0.015))
    sfs = int(s * 0.065)
    sy = int(s * 0.88)
    svg = f'''<svg xmlns="http://www.w3.org/2000/svg" width="{s}" height="{s}" viewBox="0 0 {s} {s}">
    <defs>
      <linearGradient id="bg" x1="0" y1="0" x2="1" y2="1"><stop offset="0%" stop-color="#0f1c3f"/><stop offset="100%" stop-color="#1d4ed8"/></linearGradient>
    </defs>
    <rect width="{s}" height="{s}" rx="{r}" fill="url(#bg)"/>
    <line x1="{int(s*0.05)}" y1="{int(s*0.26)}" x2="{int(s*0.38)}" y2="{int(s*0.26)}" stroke="rgba(96,165,250,0.18)" stroke-width="{lsw}" stroke-linecap="round"/>
    <line x1="{int(s*0.03)}" y1="{int(s*0.42)}" x2="{int(s*0.42)}" y2="{int(s*0.42)}" stroke="rgba(96,165,250,0.12)" stroke-width="{lsw}" stroke-linecap="round"/>
    <line x1="{int(s*0.08)}" y1="{int(s*0.58)}" x2="{int(s*0.32)}" y2="{int(s*0.58)}" stroke="rgba(96,165,250,0.08)" stroke-width="{lsw}" stroke-linecap="round"/>
    <line x1="{int(s*0.55)}" y1="{int(s*0.72)}" x2="{int(s*0.92)}" y2="{int(s*0.72)}" stroke="rgba(96,165,250,0.14)" stroke-width="{lsw}" stroke-linecap="round"/>
    <line x1="{int(s*0.60)}" y1="{int(s*0.82)}" x2="{int(s*0.95)}" y2="{int(s*0.82)}" stroke="rgba(96,165,250,0.08)" stroke-width="{lsw}" stroke-linecap="round"/>
    <rect x="{bx}" y="{by}" width="{bs}" height="{bs}" rx="{br}" fill="#fbbf24"/>
    <line x1="{ax1}" y1="{ay}" x2="{ax2}" y2="{ay}" stroke="#0f1c3f" stroke-width="{sw}" stroke-linecap="round"/>
    <line x1="{ax2}" y1="{ay}" x2="{ax2 - ah}" y2="{ay - ah}" stroke="#0f1c3f" stroke-width="{sw}" stroke-linecap="round"/>
    <line x1="{ax2}" y1="{ay}" x2="{ax2 - ah}" y2="{ay + ah}" stroke="#0f1c3f" stroke-width="{sw}" stroke-linecap="round"/>
    <text x="{tx}" y="{ty}" text-anchor="middle" font-family="Arial,Helvetica,sans-serif" font-size="{fs}" font-weight="900" fill="white">fc</text>
    <text x="{s//2}" y="{sy}" text-anchor="middle" font-family="Arial,Helvetica,sans-serif" font-size="{sfs}" font-weight="600" fill="rgba(255,255,255,0.2)" letter-spacing="{int(s*0.02)}">FASTCRAND</text>
    </svg>'''
    try:
        import cairosvg
        png = cairosvg.svg2png(bytestring=svg.encode(), output_width=size, output_height=size)
    except:
        resp = make_response(svg)
        resp.headers['Content-Type'] = 'image/svg+xml'
        return resp
    resp = make_response(png)
    resp.headers['Content-Type'] = 'image/png'
    resp.headers['Cache-Control'] = 'public, max-age=604800'
    return resp

