@app.route('/api/push/subscribe', methods=['POST'])
def api_push_subscribe():
    if 'user_id' not in session:
        return jsonify(ok=False), 401
    data = freq.get_json() or {}
    sub = data.get('subscription')
    if not sub or not isinstance(sub, dict) or not sub.get('endpoint'):
        return jsonify(ok=False, msg='No subscription')
    uid = str(session['user_id'])
    subs = _load_push_subs()
    # Migrate legacy dict format → list
    cur = subs.get(uid)
    if cur is None:
        subs[uid] = []
    elif isinstance(cur, dict):
        subs[uid] = [cur] if cur.get('endpoint') else []
    elif not isinstance(cur, list):
        subs[uid] = []
    existing = [s.get('endpoint') for s in subs[uid] if isinstance(s, dict)]
    if sub.get('endpoint') not in existing:
        subs[uid].append(sub)
        print(f" [push] new subscription saved: uid={uid} endpoint={sub.get('endpoint','')[:60]}...")
    else:
        print(f" [push] subscription already exists: uid={uid}")
    _save_push_subs(subs)
    return jsonify(ok=True)

@app.route('/api/push/unsubscribe', methods=['POST'])
def api_push_unsubscribe():
    if 'user_id' not in session:
        return jsonify(ok=False), 401
    uid = str(session['user_id'])
    subs = _load_push_subs()
    subs.pop(uid, None)
    _save_push_subs(subs)
    return jsonify(ok=True)

@app.route('/api/push/test', methods=['POST'])
def api_push_test():
    if 'user_id' not in session:
        return jsonify(ok=False, msg='not logged in'), 401
    uid = session['user_id']
    subs = _load_push_subs()
    sub_data = subs.get(str(uid))
    if not sub_data:
        return jsonify(ok=False, msg='ما عندك اشتراك إشعارات على السيرفر. افتح التطبيق وفعّل الإشعارات أولاً.')
    if not VAPID_KEYS.get('private'):
        return jsonify(ok=False, msg='VAPID keys مو مولّدة بالسيرفر')
    sub_list = sub_data if isinstance(sub_data, list) else [sub_data]
    send_push(uid, '🔔 اختبار الإشعار', 'إذا وصلتك هاي الرسالة يعني الإشعارات شغّالة 100%!')
    return jsonify(ok=True, msg=f'تم إرسال إشعار اختبار إلى {len(sub_list)} جهاز/جلسة. شيكلوگ السيرفر إذا ما وصل.')

@app.route('/api/push/test-admins', methods=['POST'])
def api_push_test_admins():
    """يحاكي إشعار طلب جديد للأدمنين — للتأكد إن إشعارات العمليات تشتغل"""
    if 'user_id' not in session or not session.get('is_admin'):
        return jsonify(ok=False, msg='admin only'), 403
    if not VAPID_KEYS.get('private'):
        return jsonify(ok=False, msg='VAPID keys مو مولّدة')
    conn = get_db()
    admins = conn.execute('SELECT id, name FROM users WHERE is_admin=1').fetchall()
    conn.close()
    subs = _load_push_subs()
    report = []
    for a in admins:
        aid = str(a['id'])
        sd = subs.get(aid)
        has_sub = bool(sd) and (
            (isinstance(sd, list) and any(isinstance(s, dict) and s.get('endpoint') for s in sd))
            or (isinstance(sd, dict) and sd.get('endpoint'))
        )
        report.append({'id': a['id'], 'name': a['name'], 'has_subscription': has_sub})
        if has_sub:
            push_user_notif(a['id'], 'admin', '🧪 اختبار إشعار أدمن', 'إذا وصلتك هاي الرسالة يعني إشعارات العمليات (طلبات/شحن/تذاكر) راح توصلك بنجاح', 'order')
    sent_count = sum(1 for r in report if r['has_subscription'])
    missing_count = len(report) - sent_count
    return jsonify(ok=True,
        msg=f'انبعث push اختباري لـ {sent_count} أدمن. {missing_count} أدمن ما عندهم اشتراك.',
        admins=report)

@app.route('/api/push/diagnostics')
def api_push_diagnostics():
    if 'user_id' not in session:
        return jsonify(ok=False), 401
    uid = str(session['user_id'])
    subs = _load_push_subs()
    sub_data = subs.get(uid)
    has_pywebpush = False
    try:
        import pywebpush  # noqa
        has_pywebpush = True
    except ImportError:
        pass
    has_pyjwt = False
    try:
        import jwt  # noqa
        has_pyjwt = True
    except ImportError:
        pass
    sub_count = 0
    endpoints = []
    if isinstance(sub_data, list):
        sub_count = len(sub_data)
        endpoints = [s.get('endpoint','')[:80]+'...' for s in sub_data if isinstance(s, dict)]
    elif isinstance(sub_data, dict):
        sub_count = 1
        endpoints = [sub_data.get('endpoint','')[:80]+'...']
    return jsonify(ok=True,
        vapid_public_key_set=bool(VAPID_KEYS.get('public')),
        vapid_private_key_set=bool(VAPID_KEYS.get('private')),
        vapid_public_key_length=len(VAPID_KEYS.get('public','')),
        pywebpush_installed=has_pywebpush,
        pyjwt_installed=has_pyjwt,
        subscription_count=sub_count,
        endpoints=endpoints,
        total_users_subscribed=len(subs)
    )

@app.route('/api/register', methods=['POST'])
def api_register():
    data = freq.get_json()
    name = (data.get('name') or '').strip()
    email = (data.get('email') or '').strip().lower()
    pw = data.get('password') or ''
    pw2 = data.get('password2') or ''

    if not name or not email or not pw:
        return jsonify(ok=False, msg='جميع الحقول مطلوبة'), 400
    if pw != pw2:
        return jsonify(ok=False, msg='كلمة المرور غير متطابقة'), 400
    if len(pw) < 6:
        return jsonify(ok=False, msg='كلمة المرور يجب أن تكون 6 أحرف على الأقل'), 400

    skip_verify = get_setting('skip_email_verify', '0') == '1'
    token = None if skip_verify else str(secrets.randbelow(900000) + 100000)
    conn = get_db()
    try:
        _pid = _next_public_id()
        conn.execute('INSERT INTO users(name,email,password,verify_token,verified,public_id) VALUES(?,?,?,?,?,?)',
                     (name, email, hash_pw(pw), token, 1 if skip_verify else 0, _pid))
        conn.commit()
        new_user = conn.execute('SELECT * FROM users WHERE email=?', (email,)).fetchone()
        ref_code = str(data.get('ref_code', '')).strip().upper()
        if ref_code and new_user:
            try:
                new_uid = new_user['id']
                _get_or_create_referral(new_uid)
                referrer = conn.execute('SELECT * FROM referrals WHERE code=?', (ref_code,)).fetchone()
                if referrer and referrer['user_id'] != new_uid:
                    conn.execute('UPDATE referrals SET referred_by=? WHERE user_id=?', (referrer['user_id'], new_uid))
                    conn.execute('UPDATE referrals SET ref_count=ref_count+1 WHERE user_id=?', (referrer['user_id'],))
                    conn.commit()
            except:
                pass
        conn.commit()
    except sqlite3.IntegrityError:
        conn.close()
        return jsonify(ok=False, msg='البريد الإلكتروني مسجل مسبقاً'), 400

    if skip_verify:
        session.permanent = True
        session['user_id'] = new_user['id']
        session['user_name'] = new_user['name']
        session['user_email'] = new_user['email']
        session['is_admin'] = bool(new_user['is_admin'])
        push_user_notif(new_user['id'], 'system', f'مرحباً بك في {get_setting("site_name","fastcrand")}! ', 'تم تفعيل حسابك بنجاح. ابدأ بشحن رصيدك وطلب خدماتك الأولى!', 'promo', goto='recharge:')
        conn.close()
        return jsonify(ok=True, msg='تم إنشاء الحساب بنجاح!', auto_login=True)

    conn.close()
    send_verify_email(email, token)
    return jsonify(ok=True, msg='تم إنشاء الحساب! تحقق من بريدك الإلكتروني')

@app.route('/api/verify-code', methods=['POST'])
def api_verify_code():
    data = freq.get_json() or {}
    email = (data.get('email') or '').strip().lower()
    code = (data.get('code') or '').strip()
    if not email or not code:
        return jsonify(ok=False, msg='أدخل الرمز')
    conn = get_db()
    user = conn.execute('SELECT * FROM users WHERE email=? AND verify_token=?', (email, code)).fetchone()
    if user:
        conn.execute('UPDATE users SET verified=1, verify_token=NULL WHERE id=?', (user['id'],))
        conn.commit()
        session['user_id'] = user['id']
        session['user_name'] = user['name']
        session['is_admin'] = bool(user['is_admin'])
        session.permanent = True
        push_user_notif(user['id'], 'system', f'مرحباً بك في {get_setting("site_name","fastcrand")}! ', 'تم تفعيل حسابك بنجاح. ابدأ بشحن رصيدك وطلب خدماتك الأولى!', 'promo', goto='recharge:')
        conn.close()
        return jsonify(ok=True, msg='تم تفعيل حسابك بنجاح!', auto_login=True)
    conn.close()
    return jsonify(ok=False, msg='الرمز غير صحيح أو منتهي الصلاحية')

@app.route('/api/resend-code', methods=['POST'])
def api_resend_code():
    data = freq.get_json() or {}
    email = (data.get('email') or '').strip().lower()
    if not email:
        return jsonify(ok=False, msg='البريد مطلوب')
    conn = get_db()
