    new_code = str(secrets.randbelow(900000) + 100000)
    conn.execute('UPDATE users SET verify_token=? WHERE id=?', (new_code, user['id']))
    conn.commit()
    conn.close()
    send_verify_email(email, new_code)
    return jsonify(ok=True, msg='تم إرسال رمز جديد')

