@app.route('/api/login', methods=['POST'])
def api_login():
    data = freq.get_json()
    identifier = (data.get('email') or data.get('username') or '').strip()
    identifier_lower = identifier.lower()
    pw = data.get('password') or ''

    conn = get_db()
    user = conn.execute(
        'SELECT * FROM users WHERE LOWER(email)=? OR LOWER(username)=?',
        (identifier_lower, identifier_lower)
    ).fetchone()

    if not user:
        conn.close()
        return jsonify(ok=False, msg='البريد أو كلمة المرور غير صحيحة'), 401

    pw_valid = False
    if user['password'] and user['password'] == hash_pw(pw):
        pw_valid = True

    if not pw_valid:
        try:
            md5_col = user['md5_password']
        except (IndexError, KeyError):
            md5_col = None
        if md5_col:
            import hashlib as _hl
            md5_hash = _hl.md5(pw.encode()).hexdigest()
            if md5_col == md5_hash:
                pw_valid = True
                conn.execute(
                    'UPDATE users SET password=?, md5_password=NULL WHERE id=?',
                    (hash_pw(pw), user['id'])
                )
                conn.commit()

    conn.close()

    if not pw_valid:
        return jsonify(ok=False, msg='البريد أو كلمة المرور غير صحيحة'), 401
    if not user['verified']:
        return jsonify(ok=False, msg='يرجى تأكيد بريدك الإلكتروني أولاً'), 403

    session.permanent = True
    session['user_id'] = user['id']
    session['user_name'] = user['name']
    session['user_email'] = user['email']
    session['is_admin'] = bool(user['is_admin'])
    return jsonify(ok=True, msg='تم تسجيل الدخول!', name=user['name'])

