@app.route('/api/change-password', methods=['POST'])
def api_change_password():
    if 'user_id' not in session:
        return jsonify(ok=False, msg='غير مصرح'), 401
    data = freq.get_json()
    old_pw = data.get('old_password', '')
    new_pw = data.get('new_password', '')
    conf_pw = data.get('confirm_password', '')
    if not old_pw or not new_pw:
        return jsonify(ok=False, msg='جميع الحقول مطلوبة')
    if new_pw != conf_pw:
        return jsonify(ok=False, msg='كلمة المرور الجديدة غير متطابقة')
    if len(new_pw) < 6:
        return jsonify(ok=False, msg='كلمة المرور يجب أن تكون 6 أحرف على الأقل')
    conn = get_db()
    user = conn.execute('SELECT password,google_id FROM users WHERE id=?', (session['user_id'],)).fetchone()
    if not user:
        conn.close()
        return jsonify(ok=False, msg='مستخدم غير موجود')
    if user['password'] and user['password'] != hash_pw(old_pw):
        conn.close()
        return jsonify(ok=False, msg='كلمة المرور الحالية غير صحيحة')
    conn.execute('UPDATE users SET password=? WHERE id=?', (hash_pw(new_pw), session['user_id']))
    conn.commit()
    conn.close()
    return jsonify(ok=True, msg='تم تغيير كلمة المرور بنجاح!')

@app.route('/api/upload-avatar', methods=['POST'])
def api_upload_avatar():
    if 'user_id' not in session:
        return jsonify(ok=False, msg='غير مصرح'), 401
    data = freq.get_json()
    img_data = data.get('image', '')
    if not img_data:
        return jsonify(ok=False, msg='لا توجد صورة')
    import base64
    if ',' in img_data:
        img_data = img_data.split(',', 1)[1]
    try:
        img_bytes = base64.b64decode(img_data)
    except Exception:
        return jsonify(ok=False, msg='صورة غير صالحة')
    if len(img_bytes) > 2 * 1024 * 1024:
        return jsonify(ok=False, msg='الصورة أكبر من 2MB')
    fname = f"av_{session['user_id']}_{int(time.time())}.jpg"
    fpath = os.path.join(AVATAR_DIR, fname)
    with open(fpath, 'wb') as f:
        f.write(img_bytes)
    avatar_url = f'/api/avatars/{fname}'
    conn = get_db()
    conn.execute('UPDATE users SET avatar=? WHERE id=?', (avatar_url, session['user_id']))
    conn.commit()
    conn.close()
    return jsonify(ok=True, url=avatar_url)

