@app.route('/api/admin/recharge-requests')
def api_admin_recharge_requests():
    if 'user_id' not in session or not session.get('is_admin'):
        return jsonify(ok=False, msg='غير مصرح'), 403
    conn = get_db()
    rows = conn.execute('''SELECT r.*, u.name as user_name, u.email as user_email 
                          FROM recharge_requests r LEFT JOIN users u ON r.user_id=u.id 
                          ORDER BY r.created_at DESC LIMIT 100''').fetchall()
    conn.close()
    reqs = []
    for r in rows:
        receipt_val = r['receipt'] or ''
        reqs.append({
            'id': r['id'], 'user_id': r['user_id'], 'user_name': r['user_name'] or '',
            'user_email': r['user_email'] or '', 'amount': r['amount'],
            'method': r['method'], 'status': r['status'],
            'has_receipt': bool(receipt_val),
            'receipt': receipt_val if len(receipt_val) < 500 else '',
            'receipt_id': r['id'],
            'date': time.strftime('%Y-%m-%d %H:%M', time.localtime(r['created_at']))
        })
    pending = sum(1 for r in reqs if r['status'] == 'pending')
    approved = sum(1 for r in reqs if r['status'] == 'approved')
    rejected = sum(1 for r in reqs if r['status'] == 'rejected')
    return jsonify(ok=True, requests=reqs, pending=pending, approved=approved, rejected=rejected, total=len(reqs))

