@app.route('/api/admin/recharge-action', methods=['POST'])
def api_admin_recharge_action():
    if 'user_id' not in session or not session.get('is_admin'):
        return jsonify(ok=False, msg='غير مصرح'), 403
    data = freq.get_json()
    rid = data.get('id')
    action = data.get('action')
    if not rid or action not in ('approve', 'reject'):
        return jsonify(ok=False, msg='بيانات غير صالحة')
    conn = get_db()
    req = conn.execute('SELECT * FROM recharge_requests WHERE id=?', (rid,)).fetchone()
    if not req:
        conn.close()
        return jsonify(ok=False, msg='الطلب غير موجود')
    if req['status'] != 'pending':
        conn.close()
        return jsonify(ok=False, msg='الطلب تمت معالجته مسبقاً')
    if action == 'approve':
        conn.execute('UPDATE recharge_requests SET status=? WHERE id=?', ('approved', rid))
        conn.execute('UPDATE users SET balance=balance+? WHERE id=?', (req['amount'], req['user_id']))
        conn.commit()
        push_user_notif(req['user_id'], 'recharge', f'تم شحن ${req["amount"]:.2f}', 'تمت الموافقة على طلب الشحن وإضافة الرصيد', 'check', goto='recharge:')
    else:
        conn.execute('UPDATE recharge_requests SET status=? WHERE id=?', ('rejected', rid))
        conn.commit()
        push_user_notif(req['user_id'], 'recharge', 'تم رفض طلب الشحن', f'طلب شحن ${req["amount"]:.2f} عبر {req["method"]} تم رفضه', 'xmark', goto='recharge:')
    conn.close()
    return jsonify(ok=True, msg='تم' if action == 'approve' else 'تم الرفض')

