@app.route('/api/admin/svc-mgmt/restore', methods=['POST'])
def api_admin_svc_mgmt_restore():
    """استعادة خدمات/فئات/منصات مخفية"""
    if 'user_id' not in session or not session.get('is_admin'):
        return jsonify(ok=False), 403
    data = freq.get_json() or {}
    rtype = data.get('type', '')  # service, category, platform
    items = data.get('items', [])
    conn = get_db()
    count = 0
    if rtype == 'platform':
        # استعادة كل عناصر المنصة
        for item in items:
            platform = (item.get('platform', '') or '').strip()
            if platform:
                cur = conn.execute('UPDATE service_filters SET hidden=0 WHERE platform=? AND hidden=1', (platform,))
                count += cur.rowcount
    else:
        for item in items:
            key = str(item.get('key', ''))
            platform = item.get('platform', '')
            if not key:
                continue
            if rtype == 'service':
                conn.execute("UPDATE service_filters SET hidden=0 WHERE filter_type='service' AND filter_key=? AND platform=?", (key, platform))
                count += 1
            elif rtype == 'category':
                conn.execute("UPDATE service_filters SET hidden=0 WHERE filter_type='category' AND filter_key=? AND platform=?", (key, platform))
                count += 1
    conn.commit()
    conn.close()
    _bump_svc_version()
    return jsonify(ok=True, msg=f'تم استعادة {count} عنصر', count=count)

@app.route('/api/admin/svc-mgmt/hidden')
def api_admin_svc_mgmt_hidden():
    """جلب العناصر المخفية"""
    if 'user_id' not in session or not session.get('is_admin'):
        return jsonify(ok=False), 403
    conn = get_db()
    frows = conn.execute("SELECT * FROM service_filters WHERE hidden=1").fetchall()
    conn.close()
    services = []
    categories = []
    platforms = {}
    for f in frows:
        ft = f['filter_type']
        fk = f['filter_key']
        fp = f['platform'] or ''
        cname = ''
        try: cname = f['custom_name'] or ''
        except: pass
        if ft == 'service':
            services.append({'key': fk, 'platform': fp, 'custom_name': cname})
        elif ft == 'category':
            categories.append({'key': fk, 'platform': fp, 'custom_name': cname})
        if fp:
            if fp not in platforms:
                platforms[fp] = {'svc': 0, 'cat': 0}
            if ft == 'service':
                platforms[fp]['svc'] += 1
            elif ft == 'category':
                platforms[fp]['cat'] += 1
    plat_list = [{'name': k, 'svc_count': v['svc'], 'cat_count': v['cat']} for k, v in platforms.items()]
    plat_list.sort(key=lambda x: x['name'])
    return jsonify(ok=True, services=services, categories=categories, platforms=plat_list,
                   total=len(services) + len(categories))

