def _get_user_level_discount(uid):
    """يحسب نسبة خصم المستوى الحالي للمستخدم بناءً على إجمالي مشترياته"""
    try:
        conn = get_db()
        row = conn.execute("SELECT COALESCE(SUM(CAST(charge AS REAL)),0) as total FROM orders WHERE user_id=? AND status='Completed'", (uid,)).fetchone()
        total_spent = float(row['total']) if row else 0
        lv_rows = conn.execute('SELECT discount, min_spent FROM levels WHERE active=1 ORDER BY min_spent ASC').fetchall()
        conn.close()
        discount = 0.0
        for lv in lv_rows:
            if total_spent >= float(lv['min_spent']):
                discount = float(lv['discount'] or 0)
        return discount
    except:
        return 0.0

@app.route('/api/order', methods=['POST'])
def api_order():
    if 'user_id' not in session:
        return jsonify(ok=False, msg='يرجى تسجيل الدخول'), 401
    data = freq.get_json()
    service = data.get('service')
    svc_name = data.get('service_name', '')
    link = data.get('link', '')
    quantity = int(data.get('quantity', 0))
    site_price = float(data.get('price', 0))
    comments = (data.get('comments') or '').strip()
    if not service or not link or not quantity:
        return jsonify(ok=False, msg='جميع الحقول مطلوبة'), 400
    _lv_disc = _get_user_level_discount(session['user_id'])
    if _lv_disc > 0 and site_price > 0:
        site_price = round(site_price * (1 - _lv_disc / 100.0), 4)
    try:
        _svcs_chk = get_smm_services() or []
        for _sc in _svcs_chk:
            if str(_sc.get('service','')) == str(service):
                _mn = int(_sc.get('min', 1))
                _mx = int(_sc.get('max', 1000000))
                if quantity < _mn:
                    return jsonify(ok=False, msg=f'الحد الأدنى للكمية {_mn:,}')
                if quantity > _mx:
                    return jsonify(ok=False, msg=f'الحد الأقصى للكمية {_mx:,}')
                break
    except: pass
    conn = get_db()
    dup = conn.execute(
        "SELECT id, status FROM orders WHERE user_id=? AND service=? AND link=? AND status NOT IN ('Completed','Canceled','Partial') ORDER BY id DESC LIMIT 1",
        (session['user_id'], service, link)
    ).fetchone()
    if dup:
        conn.close()
        return jsonify(ok=False, msg='يوجد طلب نشط لنفس الرابط ونفس الخدمة. انتظر حتى يكتمل الطلب السابق.')
    user = conn.execute('SELECT balance,is_admin FROM users WHERE id=?', (session['user_id'],)).fetchone()
    if not user:
        conn.close()
        return jsonify(ok=False, msg='مستخدم غير موجود'), 400
    bal = float(user['balance'])
    if not user['is_admin'] and site_price > 0 and bal < site_price:
        conn.close()
        return jsonify(ok=False, msg=f'رصيد غير كافي. المطلوب: ${site_price:.2f} — رصيدك: ${bal:.2f}')
    _refill_days = ''
    try:
        _svcs = get_smm_services() or []
        for _sv in _svcs:
            if str(_sv.get('service','')) == str(service):
                _rf = str(_sv.get('refill',''))
                if _rf and _rf not in ('0','False','false'):
                    _refill_days = _rf
                break
    except: pass
    if not user['is_admin'] and site_price > 0:
        conn.execute('UPDATE users SET balance=balance-? WHERE id=?', (site_price, session['user_id']))
    _api_url, _api_key, _prov_id = _find_service_provider(service)
    provider_has_balance = False
    try:
        _br = requests.post(_api_url, data={'key': _api_key, 'action': 'balance'}, timeout=10)
        _bd = _br.json()
        provider_bal = float(_bd.get('balance', 0))
        est_cost = 0
        try:
            _svcs2 = get_smm_services() or []
            for _sv2 in _svcs2:
                if str(_sv2.get('service','')) == str(service):
                    est_cost = float(_sv2.get('rate', 0)) * quantity / 1000
                    break
        except: pass
        if provider_bal >= est_cost:
            provider_has_balance = True
    except:
        provider_has_balance = True

    if provider_has_balance:
        try:
            _order_data = {
                'key': _api_key, 'action': 'add',
                'service': service, 'link': link, 'quantity': quantity
            }
            if comments:
                _order_data['comments'] = comments
            r = requests.post(_api_url, data=_order_data, timeout=15)
            result = r.json()
            if 'order' in result:
                provider_charge = float(result.get('charge', 0))
                _did = _next_display_id()
                conn.execute('INSERT INTO orders(user_id,order_id,service,service_name,link,quantity,charge,site_charge,status,refill_days,display_id,provider_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)',
                             (session['user_id'], str(result['order']), service, svc_name, link, quantity, str(provider_charge), site_price, 'Processing', _refill_days, _did, _prov_id))
                conn.commit()
                new_bal = conn.execute('SELECT balance FROM users WHERE id=?', (session['user_id'],)).fetchone()['balance']
                conn.close()
                try: _add_referral_commission(session['user_id'], str(result['order']), provider_charge)
                except: pass
                push_user_notif(session['user_id'], 'order', f'تم إرسال طلب #{_did}', f'{svc_name} — الكمية: {quantity} — ${site_price:.2f}', 'order', goto=f'order:{_did}')
                try:
                    _admconn = get_db()
                    _admins = _admconn.execute('SELECT id FROM users WHERE is_admin=1').fetchall()
                    _admconn.close()
                    print(f" [admin-notif] طلب جديد #{_did} → سأبعث لـ {len(_admins)} أدمن")
                    for _adm in _admins:
                        push_user_notif(_adm['id'], 'admin', f'طلب جديد #{_did}', f'{session.get("user_name","مستخدم")} — {svc_name} — ${site_price:.2f}', 'order')
                except Exception as _e:
                    print(f" [admin-notif] فشل بإرسال إشعار طلب جديد: {_e}")
                return jsonify(ok=True, msg='تم إرسال الطلب بنجاح!', order_id=_did, balance=round(new_bal, 2))
            elif 'error' in result and ('balance' in str(result.get('error','')).lower() or 'fund' in str(result.get('error','')).lower()):
                provider_has_balance = False
            else:
                _err_msg = str(result.get('error', '')).lower()
                # إذا الخدمة محذوفة من المزود — رد الرصيد + حذف تلقائي
                _dead_keywords = ['invalid service', 'service not found', 'not found', 'does not exist',
                                  'service is not', 'incorrect service', 'service unavailable',
                                  'service has been', 'service was removed', 'service deleted',
                                  'invalid service id', 'bad service']
                _is_dead = any(kw in _err_msg for kw in _dead_keywords)
                if _is_dead:
                    # رد الرصيد للمستخدم
                    if not user['is_admin'] and site_price > 0:
                        conn.execute('UPDATE users SET balance=balance+? WHERE id=?', (site_price, session['user_id']))
                        conn.commit()
                    # إخفاء الخدمة من service_filters
                    conn.execute("UPDATE service_filters SET hidden=1 WHERE filter_type='service' AND filter_key=?", (str(service),))
                    conn.commit()
                    conn.close()
                    _bump_svc_version()
                    _services_cache['data'] = None
                    _services_cache['time'] = 0
                    _all_services_cache['data'] = None
                    _all_services_cache['time'] = 0
                    return jsonify(ok=False, msg='هذه الخدمة تم حذفها من المزود ولم تعد متوفرة. تم إرجاع رصيدك.', service_removed=True)
                conn.close()
                return jsonify(ok=False, msg=result.get('error', 'حدث خطأ'))
        except Exception as e:
            conn.close()
            return jsonify(ok=False, msg=str(e))

    if not provider_has_balance:
        _did = _next_display_id()
        conn.execute('INSERT INTO orders(user_id,order_id,service,service_name,link,quantity,charge,site_charge,status,refill_days,display_id,provider_id,comments) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)',
                     (session['user_id'], '', service, svc_name, link, quantity, '0', site_price, 'Queued', _refill_days, _did, _prov_id, comments or ''))
        conn.commit()
        new_bal = conn.execute('SELECT balance FROM users WHERE id=?', (session['user_id'],)).fetchone()['balance']
        conn.close()
        push_user_notif(session['user_id'], 'order', 'تم استلام طلبك بنجاح', f'{svc_name} — طلبك قيد التنفيذ وسيتم معالجته قريباً', 'order')
        try:
            _admconn = get_db()
            _admins = _admconn.execute('SELECT id FROM users WHERE is_admin=1').fetchall()
            _admconn.close()
            print(f" [admin-notif] طلب queued → سأبعث لـ {len(_admins)} أدمن")
            for _adm in _admins:
                push_user_notif(_adm['id'], 'admin', 'طلب بانتظار رصيد المزود', f'{session.get("user_name","مستخدم")} — {svc_name} — ${site_price:.2f}', 'warning')
        except Exception as _e:
            print(f" [admin-notif] فشل بإرسال إشعار طلب queued: {_e}")
        return jsonify(ok=True, msg='تم استلام طلبك بنجاح! جاري المعالجة...', order_id=_did, queued=True, balance=round(new_bal, 2))

@app.route('/api/orders')
def api_orders():
    if 'user_id' not in session:
        return jsonify(ok=False, msg='login'), 401
    conn = get_db()
    rows = conn.execute('SELECT * FROM orders WHERE user_id=? ORDER BY created_at DESC LIMIT 200', (session['user_id'],)).fetchall()
    conn.close()
    orders = []
    for r in rows:
        _st = r['status']
        if _st == 'Queued':
            _st = 'Pending'
        orders.append({
            'id': r['id'],
            'order': r['display_id'] or str(r['id']), 'service': r['service'],
            'service_name': r['service_name'], 'link': r['link'],
            'quantity': r['quantity'],
            'charge': str(r['site_charge'] or 0) if 'site_charge' in r.keys() and r['site_charge'] else r['charge'],
            'status': _st,
            'provider_order': r['order_id'] or '',
            'refill_days': r['refill_days'] if 'refill_days' in r.keys() else '',
            'created_at': r['created_at'] or 0,
            'last_refill_at': r['last_refill_at'] if 'last_refill_at' in r.keys() else 0
        })
    return jsonify(ok=True, orders=orders)

@app.route('/api/user-stats')
def api_user_stats():
    if 'user_id' not in session:
        return jsonify(ok=False), 401
    uid = session['user_id']
    conn = get_db()
    user = conn.execute('SELECT balance, public_id FROM users WHERE id=?', (uid,)).fetchone()
    bal = float(user['balance']) if user else 0
    _pub_id = user['public_id'] if user and 'public_id' in user.keys() else ''
    row = conn.execute("SELECT COALESCE(SUM(CAST(charge AS REAL)),0) as total, COUNT(*) as cnt FROM orders WHERE user_id=? AND status='Completed'", (uid,)).fetchone()
    total_spent = float(row['total']) if row else 0
    completed = int(row['cnt']) if row else 0
    active = conn.execute("SELECT COUNT(*) FROM orders WHERE user_id=? AND status IN ('Processing','In progress','Queued')", (uid,)).fetchone()[0]
    pending = conn.execute("SELECT COUNT(*) FROM orders WHERE user_id=? AND status='Pending'", (uid,)).fetchone()[0]
    tickets = conn.execute("SELECT COUNT(*) FROM tickets WHERE user_id=? AND status IN ('open','waiting')", (uid,)).fetchone()[0]
    site_total_orders = conn.execute("SELECT display_id FROM orders WHERE display_id!='' AND display_id IS NOT NULL ORDER BY id DESC LIMIT 1").fetchone()
    site_total_orders = site_total_orders['display_id'] if site_total_orders else '0'
    lv_rows = conn.execute('SELECT * FROM levels WHERE active=1 ORDER BY min_spent ASC').fetchall()
    conn.close()
    levels = []
    for lv in lv_rows:
        levels.append({
            'name': lv['name'], 'name_en': lv['name_en'], 'min': float(lv['min_spent']),
            'discount': float(lv['discount']), 'color': lv['color'], 'icon': lv['icon'],
            'benefits': [b.strip() for b in (lv['benefits'] or '').split('\n') if b.strip()]
        })
    if not levels:
        levels = [{'name': 'عضو', 'name_en': 'MEMBER', 'min': 0, 'discount': 0, 'color': '#78716c', 'icon': 'fa-solid fa-user', 'benefits': []}]
    current_level = levels[0]
    next_level = levels[1] if len(levels) > 1 else None
    for i, lv in enumerate(levels):
        if total_spent >= lv['min']:
            current_level = lv
            next_level = levels[i + 1] if i + 1 < len(levels) else None
    remaining = round(next_level['min'] - total_spent, 2) if next_level else 0
    progress = 0
    if next_level:
        rng = next_level['min'] - current_level['min']
        progress = int(((total_spent - current_level['min']) / rng) * 100) if rng > 0 else 100
    else:
        progress = 100
    return jsonify(ok=True, balance=bal, total_spent=round(total_spent, 2), completed=completed,
                   active=active, pending=pending, tickets=tickets,
                   public_id=_pub_id,
                   level=current_level['name_en'], level_ar=current_level['name'],
                   level_color=current_level.get('color','#78716c'), level_icon=current_level.get('icon',''),
                   level_discount=current_level.get('discount',0), level_benefits=current_level.get('benefits',[]),
                   next_level=next_level['name'] if next_level else None,
                   next_level_en=next_level['name_en'] if next_level else None,
                   next_level_color=next_level.get('color','') if next_level else '',
                   remaining=remaining, progress=min(progress, 100),
                   site_total_orders=site_total_orders,
                   all_levels=levels)

@app.route('/api/order-status/<order_id>')
def api_order_status(order_id):
    if 'user_id' not in session:
        return jsonify(ok=False), 401
    conn = get_db()
    _row = conn.execute('SELECT order_id, provider_id FROM orders WHERE display_id=? AND user_id=?', (order_id, session['user_id'])).fetchone()
    if not _row:
        _row = conn.execute('SELECT order_id, provider_id FROM orders WHERE order_id=? AND user_id=?', (order_id, session['user_id'])).fetchone()
    conn.close()
    if not _row or not _row['order_id']:
        return jsonify(ok=False, msg='order not found')
    provider_oid = _row['order_id']
    _ord_pid = _row['provider_id'] if 'provider_id' in _row.keys() else 0
    try:
        if _ord_pid:
            _api_url, _api_key, _prov_id = get_provider_api(int(_ord_pid))
        else:
            _api_url, _api_key, _prov_id = get_provider_api()
        r = requests.post(_api_url, data={
            'key': _api_key, 'action': 'status', 'order': provider_oid
        }, timeout=15)
        result = r.json()
        if 'status' in result:
            conn = get_db()
            old = conn.execute('SELECT * FROM orders WHERE order_id=? AND user_id=?', (provider_oid, session['user_id'])).fetchone()
            new_status = result.get('status', '')
            conn.execute('UPDATE orders SET status=?, charge=? WHERE order_id=? AND user_id=?',
                         (new_status, result.get('charge', '0'), provider_oid, session['user_id']))
            if old and not old['refunded']:
                site_charge = float(old['site_charge'] or 0)
                qty = int(old['quantity'] or 0)
                remains = int(result.get('remains', 0))
                if new_status == 'Canceled' and site_charge > 0:
                    conn.execute('UPDATE users SET balance=balance+? WHERE id=?', (site_charge, session['user_id']))
                    conn.execute('UPDATE orders SET refunded=1 WHERE order_id=? AND user_id=?', (provider_oid, session['user_id']))
                    push_user_notif(session['user_id'], 'system', f'تم استرجاع ${site_charge:.2f}', f'طلب #{order_id} تم إلغاؤه — تم إرجاع المبلغ لرصيدك', 'wallet', goto='wallet:')
                elif new_status == 'Partial' and site_charge > 0 and qty > 0 and remains > 0:
                    refund_amount = round(site_charge * (remains / qty), 2)
                    if refund_amount > 0:
                        conn.execute('UPDATE users SET balance=balance+? WHERE id=?', (refund_amount, session['user_id']))
                        conn.execute('UPDATE orders SET refunded=1 WHERE order_id=? AND user_id=?', (provider_oid, session['user_id']))
                        push_user_notif(session['user_id'], 'system', f'استرجاع جزئي ${refund_amount:.2f}', f'طلب #{order_id} مكتمل جزئياً — تم إرجاع الفرق', 'wallet', goto='wallet:')
            conn.commit()
            conn.close()
        return jsonify(ok=True, data=result)
    except:
        return jsonify(ok=False)

AUTO_REFILL_INTERVAL = 24 * 3600
AUTO_REFILL_LOG = []

def _auto_refill_loop():
    time.sleep(120)
    while True:
        try:
            _run_auto_refill()
        except Exception as e:
            print(f" Auto-refill error: {e}")
        time.sleep(AUTO_REFILL_INTERVAL)

def _run_auto_refill():
    now = time.time(); total=0; success=0; failed=0; skipped=0; results=[]
    print(f"\n === بدء جولة التعويض التلقائي === {time.strftime('%Y-%m-%d %H:%M:%S')}")
    # كاش لبيانات APIs حسب prov_id
    _prov_api_cache = {}
    def _get_api(pid):
        pid = int(pid or 0)
        if pid in _prov_api_cache: return _prov_api_cache[pid]
        if pid:
            ret = get_provider_api(pid)
        else:
            ret = get_provider_api()
        _prov_api_cache[pid] = ret
        return ret
    conn = get_db()
    try:
        orders = conn.execute("SELECT * FROM orders WHERE status IN ('Completed','Partial') AND refill_days!='' AND refill_days IS NOT NULL").fetchall()
        for o in orders:
            try:
                rf_val = str(o['refill_days'] or '')
                if not rf_val or rf_val in ('0','False','false'): continue
                _base = {"order":o['order_id'],"user_id":o['user_id'],"service":(o['service_name'] or '')[:60],"rf":rf_val}
                last_rf = float(o['last_refill_at'] or 0)
                if now - last_rf < 23 * 3600:
                    skipped+=1; results.append({**_base,"status":"skipped","reason":"تم تعويضه مؤخراً"}); continue
                created = float(o['created_at'] or 0)
                if created and now - created < 24 * 3600:
                    skipped+=1; results.append({**_base,"status":"skipped","reason":"طلب جديد (أقل من 24 ساعة)"}); continue
                if rf_val.lower() not in ('true','∞'):
                    try:
                        rf_days = int(rf_val)
                        if created and now - created > rf_days * 86400:
                            skipped+=1; results.append({**_base,"status":"skipped","reason":"انتهت فترة التعويض"}); continue
                    except: pass
                total += 1
                # استخدام المزود الصحيح لكل طلب
                _ord_pid = 0
                try: _ord_pid = int(o['provider_id'] or 0)
                except: _ord_pid = 0
                _api_url, _api_key, _prov_id = _get_api(_ord_pid)
                try:
                    r = requests.post(_api_url, data={'key':_api_key,'action':'refill','order':o['order_id']}, timeout=15)
                    res = r.json()
                    if 'refill' in res:
                        success+=1
                        conn.execute('UPDATE orders SET last_refill_at=?, refill_count=refill_count+1 WHERE id=?', (now, o['id']))
                        results.append({**_base,"status":"success","refill_id":res.get("refill")})
                    else:
                        failed+=1; results.append({**_base,"status":"failed","error":str(res)[:80]})
                except Exception as e:
                    failed+=1; results.append({**_base,"status":"failed","error":str(e)[:80]})
                time.sleep(2)
            except: continue
        conn.commit()
    finally:
        conn.close()
    AUTO_REFILL_LOG.insert(0, {"date":time.strftime("%Y-%m-%d %H:%M:%S"),"total":total,"success":success,"failed":failed,"skipped":skipped,"results":results[:100]})
    if len(AUTO_REFILL_LOG) > 30: AUTO_REFILL_LOG[:] = AUTO_REFILL_LOG[:30]
    print(f" التعويض التلقائي: {success} نجح | {failed} فشل | {skipped} تخطي | من أصل {total}")

@app.route('/api/refill', methods=['POST'])
def api_refill():
    if 'user_id' not in session:
        return jsonify(ok=False, msg='يرجى تسجيل الدخول'), 401
    data = freq.get_json()
    order_id = data.get('order_id','')
    if not order_id:
        return jsonify(ok=False, msg='order_id مطلوب')
    conn = get_db()
    o = conn.execute('SELECT * FROM orders WHERE display_id=? AND user_id=?', (order_id, session['user_id'])).fetchone()
    if not o:
        o = conn.execute('SELECT * FROM orders WHERE order_id=? AND user_id=?', (order_id, session['user_id'])).fetchone()
    if not o:
        conn.close(); return jsonify(ok=False, msg='الطلب غير موجود')
    rf = str(o['refill_days'] or '')
    if not rf or rf in ('0','False','false'):
        conn.close(); return jsonify(ok=False, msg='هذا الطلب لا يدعم التعويض')
    if o['status'] not in ('Completed','Partial'):
        conn.close(); return jsonify(ok=False, msg='التعويض متاح فقط للطلبات المكتملة')
    now = time.time()
    created = float(o['created_at'] or 0)
    if created and now - created < 24 * 3600:
        conn.close(); return jsonify(ok=False, msg='التعويض يفتح بعد 24 ساعة من وقت الطلب')
    last_rf = float(o['last_refill_at'] or 0)
    if last_rf and now - last_rf < 23 * 3600:
        conn.close(); return jsonify(ok=False, msg='تم طلب تعويض مؤخراً، حاول لاحقاً')
    if rf.lower() not in ('true','∞'):
        try:
            rf_days = int(rf)
            if created and now - created > rf_days * 86400:
                conn.close(); return jsonify(ok=False, msg='انتهت فترة التعويض')
        except: pass
    try:
        _ord_pid = 0
        try: _ord_pid = int(o['provider_id'] or 0)
        except: _ord_pid = 0
        if _ord_pid:
            _api_url, _api_key, _prov_id = get_provider_api(_ord_pid)
        else:
            _api_url, _api_key, _prov_id = get_provider_api()
        r = requests.post(_api_url, data={'key':_api_key,'action':'refill','order':order_id}, timeout=15)
        res = r.json()
        if 'refill' in res:
            conn.execute('UPDATE orders SET last_refill_at=?, refill_count=refill_count+1 WHERE id=?', (now, o['id']))
            conn.commit(); conn.close()
            return jsonify(ok=True, msg='تم طلب التعويض بنجاح!', refill_id=res.get('refill'))
        conn.close()
        return jsonify(ok=False, msg=res.get('error', str(res)))
    except Exception as e:
        conn.close()
        return jsonify(ok=False, msg=str(e))

@app.route('/api/admin/auto_refill', methods=['POST'])
def api_admin_auto_refill():
    if 'user_id' not in session or not session.get('is_admin'):
        return jsonify(ok=False), 403
    data = freq.get_json() or {}
    action = data.get('action','log')
    if action == 'log':
        return jsonify(ok=True, log=AUTO_REFILL_LOG[:10])
    elif action == 'run_now':
        threading.Thread(target=_run_auto_refill, daemon=True).start()
        return jsonify(ok=True, msg='بدأ التعويض التلقائي...')
    return jsonify(ok=False, msg='unknown action')

# ============================================================
# دفع تلقائي: Binance Pay + آسياسيل (تحويل رصيد مباشر عبر SMS)
# ============================================================
import math
import urllib.parse
import urllib3
urllib3.disable_warnings(urllib3.exceptions.InsecureRequestWarning)

def _norm_currency_code(x):
    x = (x or '').strip().upper()
    if x in ('$', 'US$'):
        return 'USD'
    x = re.sub(r'[^A-Z]', '', x)
    if x in ('TETHER', 'TETHERUS'):
        return 'USDT'
    return x or 'USDT'

def _currency_equivalent(a, b):
    A, B = _norm_currency_code(a), _norm_currency_code(b)
    if A == B:
        return True
    usd_group = ('USD', 'USDT')
    return A in usd_group and B in usd_group

def verify_binance_order(pm_row, binance_order_id, expected_amount_usd):
    """يتحقق من عملية Binance Pay عبر API الحساب التجاري ويقارنها بالمبلغ المتوقع (دولار)"""
    try:
        extras = json.loads(pm_row['method_extras'] or '{}')
    except Exception:
        extras = {}
    api_key = (extras.get('api_key') or '').strip()
    api_secret = (extras.get('api_secret') or '').strip()
    if not api_key or not api_secret:
        return False, 'لم يتم إعداد مفاتيح Binance من الإدارة بعد.'
    binance_order_id = (binance_order_id or '').strip()
    if not binance_order_id:
        return False, 'الرجاء إدخال رقم عملية Binance (Order ID).'

    now_ms = int(time.time() * 1000)
    params = {
        'timestamp': now_ms,
        'status': '1',
        'startTime': now_ms - 7 * 24 * 60 * 60 * 1000,
        'endTime': now_ms,
    }
    query_string = '&'.join(f'{k}={v}' for k, v in params.items())
    signature = hmac.new(api_secret.encode(), query_string.encode(), hashlib.sha256).hexdigest()
    url = f'https://api3.binance.com/sapi/v1/pay/transactions?{query_string}&signature={signature}'
    try:
        resp = requests.get(url, headers={'X-MBX-APIKEY': api_key}, timeout=30)
        data = resp.json()
    except Exception as e:
        return False, f'تعذر الاتصال بـ Binance: {e}'

    rows = data.get('data') if isinstance(data, dict) else None
    if not isinstance(rows, list):
        return False, 'استجابة غير متوقعة من Binance. تأكد من صحة مفاتيح API.'

    found = None
    for row in rows:
        if str(row.get('orderId', '')) == binance_order_id:
            found = row
            break
    if not found:
        return False, 'لم يتم العثور على عملية دفع بهذا الرقم خلال آخر 7 أيام.'

    binance_ccy = str(found.get('currency', ''))
    if not _currency_equivalent('USD', binance_ccy):
        return False, f'عملة العملية غير مطابقة ({binance_ccy.upper()}).'

    try:
        binance_amount = float(found.get('amount', 0))
    except (TypeError, ValueError):
        binance_amount = 0.0
    if abs(binance_amount - expected_amount_usd) >= 0.0001:
        return False, f'المبلغ غير مطابق. المتوقع ${expected_amount_usd:.2f} والمستلم ${binance_amount:.2f}.'

    return True, found

class AsiaCellAPI:
    """عميل غير رسمي لواجهة تطبيق آسياسيل لتحويل الرصيد (مقتبس من التطبيق الرسمي).
    الحالة (deviceId/apiKey/pid/accessToken) عابرة بالكامل: تُبنى من dict وتُعاد كـ dict
    لتُخزَّن في session فقط، ولا تُحفظ أبداً في قاعدة البيانات أو ملفات."""

    def __init__(self, state=None):
        state = state or {}
        self.device_id = state.get('deviceId') or str(uuid.uuid4())
        self.api_key = state.get('apiKey') or secrets.token_hex(16)
        self.access_token = state.get('accessToken')
        self.pid = state.get('pid')
        self.transfer_pid = state.get('transferPid')
        self.last_url = None
        self.last_raw = None

    def _headers(self):
        h = {
            'User-Agent': 'okhttp/5.0.0-alpha.2',
            'Connection': 'Keep-Alive',
            'Accept-Encoding': 'gzip',
            'Cache-Control': 'no-cache',
            'X-OS-Version': '11',
            'X-Device-Type': '[Android][realme][RMX3834 11][TIRAMISU][HMS][4.3.7:90000325]',
            'X-ODP-APP-VERSION': '4.3.7',
            'X-FROM-APP': 'odp',
            'X-ODP-CHANNEL': 'mobile',
            'X-SCREEN-TYPE': 'false',
            'Content-Type': 'application/json; charset=UTF-8',
            'X-ODP-API-KEY': self.api_key,
            'DeviceID': self.device_id,
        }
        if self.access_token:
            h['Authorization'] = 'Bearer ' + self.access_token
        return h

    def get_state(self):
        return {'deviceId': self.device_id, 'apiKey': self.api_key,
                'accessToken': self.access_token, 'pid': self.pid,
                'transferPid': self.transfer_pid}

    def get_last_call(self):
        return {'url': self.last_url, 'raw': self.last_raw}

    @staticmethod
    def _pick(data, keys):
        for k in keys:
            if data.get(k):
                return data[k]
        return None

    @staticmethod
    def _extract_message(data, fallback):
        msg = AsiaCellAPI._pick(data, ['message', 'error', 'errorMessage', 'desc'])
        if msg:
            return msg
        next_action = data.get('nextAction')
        if next_action:
            try:
                q = urllib.parse.urlparse(next_action).query
                params = dict(urllib.parse.parse_qsl(q))
                if params.get('msg'):
                    return params['msg']
            except Exception:
                pass
        return fallback

    def _post_json(self, url, payload):
        self.last_url = url
        try:
            resp = requests.post(url, data=json.dumps(payload), headers=self._headers(), timeout=30, verify=False)
            self.last_raw = resp.text
        except Exception as e:
            self.last_raw = f'connection error: {e}'
            return None
        try:
            data = resp.json()
            return data if isinstance(data, dict) else None
        except Exception:
            return None

    # الخطوة 1: تسجيل الدخول برقم الهاتف وإرسال رمز SMS
    def login(self, phone_number):
        data = self._post_json('https://odpapp.asiacell.com/api/v1/login?lang=en', {
            'captchaCode': '', 'username': phone_number})
        if not data:
            return False, 'لا يوجد رد من خادم آسياسيل، حاول لاحقاً.'
        if data.get('success') is False:
            return False, self._extract_message(data, 'فشل إرسال رمز التحقق إلى هذا الرقم.')
        pid = self._pick(data, ['PID', 'pid'])
        if not pid and data.get('nextUrl'):
            m = re.search(r'PID=([a-zA-Z0-9\-]+)', data['nextUrl'])
            if m: pid = m.group(1)
        if not pid:
            return False, self._extract_message(data, 'تعذر بدء عملية تسجيل الدخول.')
        self.pid = pid
        return True, self.pid

    # الخطوة 2: التحقق من رمز SMS الأول (تأكيد رقم الهاتف)
    def verify_sms(self, passcode):
        data = self._post_json('https://odpapp.asiacell.com/api/v1/smsvalidation?lang=en', {
            'PID': self.pid, 'passcode': passcode, 'token': ''})
        if not data:
            return False, 'لا يوجد رد من خادم آسياسيل، حاول لاحقاً.'
        token = self._pick(data, ['access_token', 'accessToken', 'token'])
        if data.get('success') is False or not token:
            return False, self._extract_message(data, 'رمز التحقق غير صحيح.')
        self.access_token = token
        return True, self.access_token

    # الخطوة 3: بدء تحويل الرصيد (يرسل رمز SMS ثانٍ للتأكيد)
    def start_transfer(self, amount_iqd, receiver_msisdn):
        data = self._post_json('https://odpapp.asiacell.com/api/v1/credit-transfer/start?lang=ar', {
            'amount': int(amount_iqd), 'receiverMsisdn': receiver_msisdn})
        if not data:
            return False, 'لا يوجد رد من خادم آسياسيل، حاول لاحقاً.'
        pid = self._pick(data, ['PID', 'pid'])
        if not pid and data.get('nextUrl'):
            m = re.search(r'PID=([a-zA-Z0-9\-]+)', data['nextUrl'])
            if m: pid = m.group(1)
        if not pid:
            return False, self._extract_message(data, 'تعذر بدء عملية التحويل.')
        self.transfer_pid = pid
        return True, pid

    # الخطوة 4: تأكيد التحويل برمز SMS الثاني
    def confirm_transfer(self, passcode):
        data = self._post_json('https://odpapp.asiacell.com/api/v1/credit-transfer/do-transfer?lang=ar', {
            'PID': self.transfer_pid, 'passcode': passcode})
        if not data:
            return False, 'لا يوجد رد من خادم آسياسيل، حاول لاحقاً.'
        if data.get('success'):
            return True, data
        return False, self._extract_message(data, 'فشل تأكيد التحويل.')

def log_asiacell_debug(step, api):
    call = api.get_last_call()
    raw = str(call.get('raw') or '')
    set_setting('asiacell_last_debug', json.dumps({
        'step': step, 'url': call.get('url'), 'raw': raw[:1500],
        'time': time.strftime('%Y-%m-%d %H:%M:%S'),
    }, ensure_ascii=False))

