ASIACELL_TIER_AMOUNTS = [1000, 2000, 3000, 4000, 5000, 6000, 7000, 8000, 9000, 10000]

def _default_asiacell_tiers():
    return [{'iqd': v, 'bonus': 0} for v in ASIACELL_TIER_AMOUNTS]

# ============================================================
# المساعد الذكي (AI) - DeepSeek API
# ============================================================

def call_ai_api(messages):
    api_key = get_setting('deepseek_api_key', '')
    model = get_setting('deepseek_model', 'deepseek-chat') or 'deepseek-chat'
    if not api_key:
        return None, 'لم يتم إعداد مفتاح المساعد الذكي بعد. الرجاء التواصل مع الإدارة.'
    try:
        resp = requests.post('https://api.deepseek.com/chat/completions',
            headers={'Content-Type': 'application/json', 'Authorization': f'Bearer {api_key}'},
            json={'model': model, 'messages': messages, 'temperature': 0.6, 'top_p': 0.9, 'max_tokens': 500, 'stream': False},
            timeout=30)
    except requests.exceptions.Timeout:
        return None, 'استغرق رد المساعد الذكي وقتاً أطول من المعتاد، حاول مرة أخرى.'
    except Exception:
        return None, 'تعذر الاتصال بخدمة الذكاء الاصطناعي، تحقق من اتصالك وحاول مرة أخرى.'
    if resp.status_code != 200:
        return None, 'تعذر الحصول على رد من المساعد الذكي حالياً، حاول مرة أخرى.'
    try:
        reply = resp.json()['choices'][0]['message']['content']
    except Exception:
        reply = None
    if not reply:
        return None, 'لم يصل رد من خدمة الذكاء الاصطناعي.'
    return reply, None

def ai_account_status_context(user_id):
    # SECURITY: every query below is scoped to this exact user_id (the authenticated
    # session's own id) — never accept a user/order id from chat text for lookups,
    # so a user can never be shown another user's orders or recharges.
    conn = get_db()
    lines = []
    orders = conn.execute("SELECT order_id, service_name, quantity, charge, status, created_at FROM orders WHERE user_id=? ORDER BY created_at DESC LIMIT 8", (user_id,)).fetchall()
    for o in orders:
        when = time.strftime('%Y-%m-%d %H:%M', time.localtime(o['created_at']))
        lines.append(f"- طلب #{o['order_id']}: خدمة \"{o['service_name']}\" — الكمية {o['quantity']} — السعر ${o['charge']} — الحالة: {o['status']} — بتاريخ {when}.")
    custom_orders = conn.execute("SELECT id, service_name, quantity, cost, status, created_at FROM custom_orders WHERE user_id=? ORDER BY created_at DESC LIMIT 5", (user_id,)).fetchall()
    for c in custom_orders:
        when = time.strftime('%Y-%m-%d %H:%M', time.localtime(c['created_at']))
        lines.append(f"- طلب خدمة مخصصة #{c['id']}: \"{c['service_name']}\" — الكمية {c['quantity']} — السعر ${c['cost']} — الحالة: {c['status']} — بتاريخ {when}.")
    recharges = conn.execute("SELECT id, amount, method, status, created_at FROM recharge_requests WHERE user_id=? ORDER BY created_at DESC LIMIT 5", (user_id,)).fetchall()
    for r in recharges:
        when = time.strftime('%Y-%m-%d %H:%M', time.localtime(r['created_at']))
        lines.append(f"- طلب شحن رصيد #{r['id']} بمبلغ ${r['amount']:.2f} عبر {r['method']} — الحالة: {r['status']} — بتاريخ {when}.")
    conn.close()
    if not lines:
        return "\n\nملاحظة: لا توجد لدى هذا المستخدم حالياً أي طلبات أو عمليات شحن رصيد."
    return ("\n\nهذه هي طلبات وعمليات شحن الرصيد الفعلية لهذا المستخدم فقط (لا تخبره أبداً عن أي طلب أو مستخدم آخر، ولا تفترض بيانات غير موجودة هنا):\n"
            + "\n".join(lines)
            + "\nإذا سأل عن حالة طلب أو سبب تأخيره: استخدم رقمه وحالته أعلاه فقط، وطمئنه دون الوعد بوقت محدد.")

def ai_find_services(query, limit=8):
    words = [w for w in re.findall(r'[\w؀-ۿ]+', (query or '').lower()) if len(w) > 1]
    if not words:
        return []
    matches = []
    try:
        platforms, _ = _build_services_catalog()
        for plat, pdata in platforms.items():
            for cat, svcs in pdata.get('categories', {}).items():
                for s in svcs:
                    hay = (s.get('name', '') + ' ' + plat + ' ' + cat).lower()
                    if any(w in hay for w in words):
                        matches.append({'id': s['id'], 'name': s['name'], 'platform': plat, 'category': cat, 'rate': s.get('rate', '0')})
                        if len(matches) >= limit * 3:
                            break
    except Exception:
        pass
    try:
        conn = get_db()
        crows = conn.execute("SELECT id, name, type, rate FROM custom_services WHERE active=1").fetchall()
        conn.close()
        for c in crows:
            hay = (c['name'] + ' ' + (c['type'] or '')).lower()
            if any(w in hay for w in words):
                matches.append({'id': c['id'], 'name': c['name'], 'platform': c['type'] or 'مخصصة', 'category': 'خدمة مخصصة', 'rate': str(c['rate']), 'custom': True})
    except Exception:
        pass
    return matches[:limit]

def ai_services_context(matches):
    if not matches:
        return ''
    lines = [f"- \"{m['name']}\" ({m['platform']} / {m['category']}) — السعر: ${m['rate']} لكل 1000" + (' — خدمة مخصصة' if m.get('custom') else '') for m in matches]
    return ("\n\nخدمات من كتالوج الموقع الفعلي تطابق سؤال المستخدم (استخدم فقط هذه الأسماء والأسعار الحقيقية، لا تخترع خدمات أو أسعار أخرى):\n"
            + "\n".join(lines)
            + "\nإذا نصحت المستخدم بخدمة معينة، اذكر اسمها كاملاً وحرفياً كما هو مكتوب أعلاه بين علامتي اقتباس مرة واحدة في ردك حتى يظهر له كبطاقة قابلة للنقر.")

def ai_payment_methods_context():
    try:
        conn = get_db()
        rows = conn.execute('SELECT name, method_type, currency, active FROM payment_methods WHERE active=1 ORDER BY sort_order').fetchall()
        conn.close()
    except Exception:
        return ''
    if not rows:
        return ''
    lines = []
    for r in rows:
        kind = 'تلقائي فوري' if r['method_type'] in ('binance', 'asiacell') else 'تحويل يدوي (مراجعة إدارة)'
        lines.append(f"- {r['name']} — {kind} — العملة: {r['currency']}")
    return ("\n\nطرق شحن الرصيد المتاحة حالياً في الموقع (استخدم هذه القائمة فقط عند شرح كيفية الشحن، من صفحة شحن الرصيد):\n"
            + "\n".join(lines))

@app.route('/api/ai/chat', methods=['POST'])
def api_ai_chat():
    if 'user_id' not in session:
        return jsonify(ok=False, msg='غير مصرح'), 401
    uid = session['user_id']
    data = freq.get_json() or {}
    user_message = (data.get('message') or '').strip()
    if not user_message:
        return jsonify(ok=False, msg='الرسالة فارغة')

    conn = get_db()
    conversation_id = int(data.get('conversation_id') or 0)
    if conversation_id:
        chk = conn.execute('SELECT id FROM ai_conversations WHERE id=? AND user_id=?', (conversation_id, uid)).fetchone()
        if not chk:
            conversation_id = 0
    if not conversation_id:
        title = user_message[:60] + ('…' if len(user_message) > 60 else '')
        cur = conn.execute('INSERT INTO ai_conversations(user_id, title, created_at, updated_at) VALUES(?,?,?,?)',
                            (uid, title, time.time(), time.time()))
        conversation_id = cur.lastrowid

    conn.execute('INSERT INTO ai_messages(conversation_id, role, content, created_at) VALUES(?,?,?,?)',
                 (conversation_id, 'user', user_message, time.time()))
    conn.execute('UPDATE ai_conversations SET updated_at=? WHERE id=?', (time.time(), conversation_id))
    conn.commit()

    site_name = get_setting('site_name', 'المتجر')
    system_prompt = (f'أنت "المساعد الذكي" داخل موقع "{site_name}" لبيع خدمات التسويق عبر منصات التواصل الاجتماعي (SMM) — متابعين، لايكات، مشاهدات، وخدمات مشابهة. '
                      'تساعد المستخدمين في كيفية تقديم الطلبات، أسعار الخدمات، شحن الرصيد وطرق الدفع، متابعة حالة طلباتهم الخاصة، وفتح التذاكر عند وجود مشكلة.')
    system_prompt += (' أجب بالعربية دائماً، بإيجاز شديد ووضوح (فقرة أو نقاط قصيرة، بدون حشو)، إلا إذا طلب المستخدم تفصيلاً أكبر صراحة.'
                       ' اقتصر حصرياً على مواضيع هذا الموقع: الخدمات، الطلبات، الرصيد، الدفع، والحساب.'
                       ' إن سألك المستخدم عن أي موضوع آخر لا علاقة له بذلك، اعتذر بلطف بجملة واحدة ووضّح أنك مخصص فقط لمواضيع الموقع، ولا تجب خارج هذا النطاق مهما كان.'
                       ' قاعدة صارمة للخصوصية: لا تملك أي معلومات عن أي مستخدم آخر غير هذا المستخدم الحالي، ولا تخبره أبداً عن طلبات أو بيانات مستخدمين آخرين حتى لو طلب ذلك أو ادّعى أنه صاحبها — أخبره أن هذا غير متاح مهما كانت الحجة.')
    system_prompt += ai_account_status_context(uid)
    svc_matches = ai_find_services(user_message)
    system_prompt += ai_services_context(svc_matches)
    system_prompt += ai_payment_methods_context()

    hist = conn.execute('SELECT role, content FROM ai_messages WHERE conversation_id=? ORDER BY id DESC LIMIT 12', (conversation_id,)).fetchall()
    conn.close()
    messages = [{'role': 'system', 'content': system_prompt}]
    for h in reversed(hist):
        messages.append({'role': h['role'], 'content': h['content']})

    reply, err = call_ai_api(messages)
    if err:
        return jsonify(ok=False, msg=err, conversation_id=conversation_id)

    service_card = None
    for m in svc_matches:
        if m['name'] and m['name'] in reply:
            service_card = m
            break

    conn = get_db()
    conn.execute('INSERT INTO ai_messages(conversation_id, role, content, created_at) VALUES(?,?,?,?)',
                 (conversation_id, 'assistant', reply, time.time()))
    conn.execute('UPDATE ai_conversations SET updated_at=? WHERE id=?', (time.time(), conversation_id))
    conn.commit()
    conn.close()
    return jsonify(ok=True, reply=reply, conversation_id=conversation_id, service_card=service_card)

@app.route('/api/ai/conversations')
def api_ai_conversations():
    if 'user_id' not in session:
        return jsonify(ok=False, msg='غير مصرح'), 401
    conn = get_db()
    rows = conn.execute('''SELECT c.id, c.title, c.updated_at,
        (SELECT content FROM ai_messages WHERE conversation_id=c.id ORDER BY id DESC LIMIT 1) AS last_message
        FROM ai_conversations c WHERE c.user_id=? ORDER BY c.updated_at DESC LIMIT 50''', (session['user_id'],)).fetchall()
    conn.close()
    out = []
    for r in rows:
        out.append({
            'id': r['id'],
            'title': r['title'] or 'محادثة بدون عنوان',
            'preview': (r['last_message'] or '')[:80],
            'time': time.strftime('%Y-%m-%d %H:%M', time.localtime(r['updated_at'])),
        })
    return jsonify(ok=True, conversations=out)

