@app.route('/api/ai/clear', methods=['POST'])
def api_ai_clear():
    if 'user_id' not in session:
        return jsonify(ok=False, msg='غير مصرح'), 401
    uid = session['user_id']
    conn = get_db()
    ids = [r['id'] for r in conn.execute('SELECT id FROM ai_conversations WHERE user_id=?', (uid,)).fetchall()]
    if ids:
        qs = ','.join('?' * len(ids))
        conn.execute(f'DELETE FROM ai_messages WHERE conversation_id IN ({qs})', ids)
        conn.execute(f'DELETE FROM ai_conversations WHERE id IN ({qs})', ids)
        conn.commit()
    conn.close()
    return jsonify(ok=True, msg='تم مسح جميع المحادثات')

@app.route('/api/payment-methods')
def api_pm_public():
    if 'user_id' not in session:
        return jsonify(ok=False), 401
    conn = get_db()
    rows = conn.execute('SELECT * FROM payment_methods WHERE active=1 ORDER BY sort_order ASC, created_at DESC').fetchall()
    conn.close()
    methods = []
    for r in rows:
        mtype = r['method_type'] if 'method_type' in r.keys() else 'manual'
        qr_code = ''
        tiers = None
        if mtype == 'binance':
            try:
                qr_code = (json.loads(r['method_extras'] or '{}') or {}).get('qr_code', '')
            except Exception:
                qr_code = ''
        if mtype == 'asiacell':
            try:
                tiers = (json.loads(r['method_extras'] or '{}') or {}).get('tiers') or _default_asiacell_tiers()
            except Exception:
                tiers = _default_asiacell_tiers()
        methods.append({
            'id': r['id'], 'name': r['name'], 'icon': r['icon'],
            'number': r['number'], 'exchange_rate': r['exchange_rate'],
            'currency': r['currency'], 'note': r['note'],
            'bot_link': r['bot_link'] if 'bot_link' in r.keys() else '',
            'image': r['image'] if 'image' in r.keys() else '',
            'method_type': mtype,
            'qr_code': qr_code,
            'tiers': tiers
        })
    return jsonify(ok=True, methods=methods)

