@app.route('/api/admin/payment-methods', methods=['POST'])
def api_pm_add():
    if 'user_id' not in session or not session.get('is_admin'):
        return jsonify(ok=False), 403
    data = freq.get_json()
    name = (data.get('name') or '').strip()
    if not name:
        return jsonify(ok=False, msg='اسم الطريقة مطلوب')
    pm_image = ''
    img_data = data.get('image_data', '')
    if img_data and ',' in img_data:
        try:
            import base64
            header, b64 = img_data.split(',', 1)
            ext = 'png'
            if 'jpeg' in header or 'jpg' in header: ext = 'jpg'
            elif 'webp' in header: ext = 'webp'
            elif 'gif' in header: ext = 'gif'
            fname = f'pm_{uuid.uuid4().hex[:12]}.{ext}'
            fpath = os.path.join(PM_IMG_DIR, fname)
            with open(fpath, 'wb') as f:
                f.write(base64.b64decode(b64))
            pm_image = fname
        except Exception as e:
            pass
    conn = get_db()
    # هذا المسار لطرق الدفع اليدوية فقط؛ Binance وآسياسيل ثابتتان (راجع /api/admin/payment-methods/binance|asiacell)
    conn.execute("INSERT INTO payment_methods(name,icon,number,exchange_rate,currency,note,bot_link,image,active,method_type) VALUES(?,?,?,?,?,?,?,?,?,'manual')",
                 (name, data.get('icon','fa-solid fa-credit-card'), data.get('number',''),
                  data.get('exchange_rate',''), data.get('currency','IQD'),
                  data.get('note',''), data.get('bot_link',''), pm_image,
                  1 if data.get('active', True) else 0))
    conn.commit()
    conn.close()
    return jsonify(ok=True, msg='تم إضافة طريقة الدفع')

@app.route('/api/admin/payment-methods/<int:pm_id>', methods=['PUT'])
def api_pm_edit(pm_id):
    if 'user_id' not in session or not session.get('is_admin'):
        return jsonify(ok=False), 403
    data = freq.get_json()
    img_data = data.get('image_data', '')
    conn = get_db()
    _type_row = conn.execute('SELECT method_type FROM payment_methods WHERE id=?', (pm_id,)).fetchone()
    if _type_row and _type_row['method_type'] and _type_row['method_type'] != 'manual':
        conn.close()
        return jsonify(ok=False, msg='لا يمكن تعديل هذه الطريقة من هنا. استخدم إعدادات Binance/آسياسيل.')
    if img_data and ',' in img_data:
        try:
            import base64
            header, b64 = img_data.split(',', 1)
            ext = 'png'
            if 'jpeg' in header or 'jpg' in header: ext = 'jpg'
            elif 'webp' in header: ext = 'webp'
            elif 'gif' in header: ext = 'gif'
            fname = f'pm_{uuid.uuid4().hex[:12]}.{ext}'
            fpath = os.path.join(PM_IMG_DIR, fname)
            with open(fpath, 'wb') as f:
                f.write(base64.b64decode(b64))
            old = conn.execute('SELECT image FROM payment_methods WHERE id=?', (pm_id,)).fetchone()
            if old and old['image']:
                old_path = os.path.join(PM_IMG_DIR, old['image'])
                if os.path.exists(old_path):
                    try: os.remove(old_path)
                    except: pass
            conn.execute('UPDATE payment_methods SET image=? WHERE id=?', (fname, pm_id))
        except Exception as e:
            pass
    elif img_data == '__remove__':
        old = conn.execute('SELECT image FROM payment_methods WHERE id=?', (pm_id,)).fetchone()
        if old and old['image']:
            old_path = os.path.join(PM_IMG_DIR, old['image'])
            if os.path.exists(old_path):
                try: os.remove(old_path)
                except: pass
        conn.execute('UPDATE payment_methods SET image=? WHERE id=?', ('', pm_id))
    conn.execute('''UPDATE payment_methods SET name=?,icon=?,number=?,exchange_rate=?,currency=?,note=?,bot_link=?,active=? WHERE id=?''',
                 (data.get('name',''), data.get('icon','fa-solid fa-credit-card'), data.get('number',''),
                  data.get('exchange_rate',''), data.get('currency','IQD'),
                  data.get('note',''), data.get('bot_link',''),
                  1 if data.get('active', True) else 0, pm_id))
    conn.commit()
    conn.close()
    return jsonify(ok=True, msg='تم تحديث طريقة الدفع')

