def _save_pm_image(img_data, fallback):
    """يحفظ صورة PM المرسلة كـ data URL إن وُجدت، أو يحذفها إذا كانت '__remove__'، وإلا يُعيد الصورة الحالية (fallback)"""
    if img_data == '__remove__':
        return ''
    if not (img_data and ',' in img_data):
        return fallback
    try:
        import base64
        header, b64 = img_data.split(',', 1)
        ext = 'png'
        if 'jpeg' in header or 'jpg' in header: ext = 'jpg'
        elif 'webp' in header: ext = 'webp'
        elif 'gif' in header: ext = 'gif'
        fname = f'pm_{uuid.uuid4().hex[:12]}.{ext}'
        with open(os.path.join(PM_IMG_DIR, fname), 'wb') as f:
            f.write(base64.b64decode(b64))
        return fname
    except Exception:
        return fallback

@app.route('/api/admin/payment-methods/binance', methods=['POST'])
def api_pm_save_binance():
    if 'user_id' not in session or not session.get('is_admin'):
        return jsonify(ok=False), 403
    data = freq.get_json() or {}
    conn = get_db()
    row = conn.execute("SELECT * FROM payment_methods WHERE method_type='binance' LIMIT 1").fetchone()
    if not row:
        conn.close()
        return jsonify(ok=False, msg='تعذر العثور على طريقة Binance Pay.')
    try:
        extras = json.loads(row['method_extras'] or '{}')
    except Exception:
        extras = {}
    api_key = (data.get('api_key') or '').strip()
    api_secret = (data.get('api_secret') or '').strip()
    binance_id = (data.get('binance_id') or '').strip()
    # حقل فارغ يُبقي على المفتاح الحالي (لا نُجبر الأدمن على إعادة كتابته في كل حفظ)
    if api_key: extras['api_key'] = api_key
    if api_secret: extras['api_secret'] = api_secret
    pm_image = _save_pm_image(data.get('image_data', ''), row['image'] if 'image' in row.keys() else '')
    qr_code = _save_pm_image(data.get('qr_data', ''), extras.get('qr_code', ''))
    extras['qr_code'] = qr_code
    conn.execute('UPDATE payment_methods SET number=?, image=?, active=?, method_extras=? WHERE id=?',
                 (binance_id, pm_image, 1 if data.get('active') else 0, json.dumps(extras), row['id']))
    conn.commit()
    conn.close()
    return jsonify(ok=True, msg='تم حفظ إعدادات Binance Pay')

@app.route('/api/admin/payment-methods/asiacell', methods=['POST'])
def api_pm_save_asiacell():
    if 'user_id' not in session or not session.get('is_admin'):
        return jsonify(ok=False), 403
    data = freq.get_json() or {}
    conn = get_db()
    row = conn.execute("SELECT * FROM payment_methods WHERE method_type='asiacell' LIMIT 1").fetchone()
    if not row:
        conn.close()
        return jsonify(ok=False, msg='تعذر العثور على طريقة آسياسيل.')
    try:
        extras = json.loads(row['method_extras'] or '{}')
    except Exception:
        extras = {}
    receiver = (data.get('receiver_msisdn') or '').strip()
    try:
        exchange_rate = float(data.get('exchange_rate') or 0)
    except (TypeError, ValueError):
        exchange_rate = 0
    try:
        max_transfer = int(data.get('max_transfer') or 10000)
    except (TypeError, ValueError):
        max_transfer = 10000
    if max_transfer < 1000:
        max_transfer = 10000
    extras['max_transfer'] = max_transfer
    tiers_in = data.get('tiers')
    if isinstance(tiers_in, list) and tiers_in:
        clean_tiers = []
        for t in tiers_in:
            try:
                iqd = int(t.get('iqd'))
                bonus = float(t.get('bonus') or 0)
            except (TypeError, ValueError, AttributeError):
                continue
            if iqd in ASIACELL_TIER_AMOUNTS:
                clean_tiers.append({'iqd': iqd, 'bonus': max(0, bonus)})
        if clean_tiers:
            extras['tiers'] = clean_tiers
    pm_image = _save_pm_image(data.get('image_data', ''), row['image'] if 'image' in row.keys() else '')
    conn.execute('UPDATE payment_methods SET number=?, exchange_rate=?, note=?, image=?, active=?, method_extras=? WHERE id=?',
                 (receiver, str(exchange_rate) if exchange_rate else '', data.get('note', row['note'] or ''),
                  pm_image, 1 if data.get('active') else 0, json.dumps(extras), row['id']))
    conn.commit()
    conn.close()
    return jsonify(ok=True, msg='تم حفظ إعدادات آسياسيل')

