@app.route('/api/pm-image/<fname>')
def api_pm_image(fname):
    fname = fname.replace('..', '').replace('/', '')
    fpath = os.path.join(PM_IMG_DIR, fname)
    if not os.path.exists(fpath):
        pass
        try:
            conn = get_db()
            conn.execute('UPDATE payment_methods SET image=? WHERE image=?', ('', fname))
            conn.commit()
            conn.close()
        except Exception as e:
            pass
        return '', 404
    ext = fname.rsplit('.', 1)[-1].lower() if '.' in fname else 'png'
    mime = {'png': 'image/png', 'jpg': 'image/jpeg', 'jpeg': 'image/jpeg', 'gif': 'image/gif', 'webp': 'image/webp'}.get(ext, 'image/png')
    return send_file(fpath, mimetype=mime, max_age=86400)

@app.route('/api/admin/users')
def api_admin_users():
    if 'user_id' not in session or not session.get('is_admin'):
        return jsonify(ok=False), 403
    conn = get_db()
    rows = conn.execute('SELECT id,name,email,balance,banned,is_admin,public_id FROM users ORDER BY created_at DESC').fetchall()
    conn.close()
    users = []
    for r in rows:
        users.append({
            'id': r['id'], 'name': r['name'], 'email': r['email'],
            'balance': r['balance'] or 0, 'banned': r['banned'] or 0,
            'is_admin': r['is_admin'] or 0,
            'public_id': r['public_id'] if 'public_id' in r.keys() else ''
        })
    total = len(users)
    active = sum(1 for u in users if not u['banned'])
    banned = sum(1 for u in users if u['banned'])
    return jsonify(ok=True, users=users, total=total, active=active, banned=banned)

@app.route('/api/admin/users/<int:uid>/balance', methods=['POST'])
def api_admin_balance(uid):
    if 'user_id' not in session or not session.get('is_admin'):
        return jsonify(ok=False), 403
    data = freq.get_json()
    action = data.get('action', '')
    amount = float(data.get('amount', 0))
    if amount <= 0:
        return jsonify(ok=False, msg='المبلغ يجب أن يكون أكبر من 0')
    conn = get_db()
    user = conn.execute('SELECT balance FROM users WHERE id=?', (uid,)).fetchone()
    if not user:
        conn.close()
        return jsonify(ok=False, msg='المستخدم غير موجود')
    current = user['balance'] or 0
    if action == 'add':
        new_bal = current + amount
    elif action == 'sub':
        new_bal = max(0, current - amount)
    else:
        conn.close()
        return jsonify(ok=False, msg='إجراء غير صالح')
    conn.execute('UPDATE users SET balance=? WHERE id=?', (new_bal, uid))
    conn.commit()
    if action == 'add':
        push_user_notif(uid, 'recharge', f'تم إضافة ${amount:.2f} لرصيدك', f'رصيدك الجديد: ${new_bal:.2f}', 'wallet')
    else:
        push_user_notif(uid, 'system', f'تم خصم ${amount:.2f} من رصيدك', f'رصيدك الجديد: ${new_bal:.2f}', 'wallet')
    conn.close()
    return jsonify(ok=True, msg='تم تحديث الرصيد', new_balance=new_bal)

