@app.route('/api/tickets', methods=['POST'])
def api_tickets():
    if 'user_id' not in session:
        return jsonify(ok=False, error='unauthorized'), 401
    uid = session['user_id']
    conn = get_db()
    rows = conn.execute('SELECT * FROM tickets WHERE user_id=? ORDER BY created_at DESC', (uid,)).fetchall()
    result = []
    for t in rows:
        msgs = conn.execute('SELECT * FROM ticket_messages WHERE ticket_id=? ORDER BY created_at ASC', (t['id'],)).fetchall()
        clean_msgs = []
        for m in msgs:
            cm = {'from': m['sender'], 'text': m['text'], 'time': time.strftime('%d/%m %H:%M', time.localtime(m['created_at']))}
            if m['msg_type'] == 'voice':
                cm['type'] = 'voice'
                cm['url'] = m['voice_url']
                cm['duration'] = m['duration']
            elif m['msg_type'] == 'image':
                cm['type'] = 'image'
                cm['url'] = m['voice_url']
            clean_msgs.append(cm)
        result.append({
            'id': t['id'], 'subject': t['subject'], 'category': t['category'],
            'status': t['status'], 'date': time.strftime('%d/%m %H:%M', time.localtime(t['created_at'])),
            'messages': clean_msgs
        })
    conn.close()
    return jsonify(ok=True, tickets=result)

@app.route('/api/tickets/create', methods=['POST'])
def api_ticket_create():
    if 'user_id' not in session:
        return jsonify(ok=False, error='unauthorized'), 401
    uid = session['user_id']
    data = freq.json or {}
    subj = data.get('subject', '').strip()
    desc = data.get('description', '').strip()
    cat = data.get('category', 'عام')
