@app.route('/api/tickets/voice', methods=['POST'])
def api_ticket_voice():
    if 'user_id' not in session:
        return jsonify(ok=False, error='unauthorized'), 401
    data = freq.json or {}
    tid = data.get('ticket_id', '')
    audio = data.get('audio', '')
    dur = data.get('duration', 0)
    if not audio or not tid:
        return jsonify(ok=False, error='missing data')
    if len(audio) > 5_000_000:
        return jsonify(ok=False, error='too large')
    conn = get_db()
    t = conn.execute('SELECT * FROM tickets WHERE id=? AND user_id=?', (tid, session['user_id'])).fetchone()
    if not t:
        conn.close()
        return jsonify(ok=False, error='not found')
    import base64 as _b64
    fname = f'v_{tid}_{uuid.uuid4().hex[:8]}.webm'
    fpath = os.path.join(VOICE_DIR, fname)
    try:
        with open(fpath, 'wb') as f:
            f.write(_b64.b64decode(audio))
    except:
        conn.close()
        return jsonify(ok=False, error='invalid audio')
    voice_url = f'/api/voice/{fname}'
    conn.execute('INSERT INTO ticket_messages(ticket_id,sender,msg_type,voice_url,duration) VALUES(?,?,?,?,?)',
                 (tid, 'user', 'voice', voice_url, dur))
    conn.execute('UPDATE tickets SET status=? WHERE id=?', ('waiting', tid))
    conn.commit()
    admins = conn.execute('SELECT id FROM users WHERE is_admin=1').fetchall()
    for a in admins:
        push_user_notif(a['id'], 'admin', f'رسالة صوتية في تذكرة #TK-{tid}', f'من {session.get("user_name","مستخدم")}', 'message', goto=f'ticket:{tid}')
    conn.close()
    return jsonify(ok=True, voice_url=voice_url)

@app.route('/api/voice/<fname>')
def serve_voice(fname):
    import re as _re2
    if not _re2.match(r'^[a-zA-Z0-9_\-]+\.webm$', fname):
        return 'not found', 404
    fpath = os.path.join(VOICE_DIR, fname)
    if not os.path.exists(fpath):
        return 'not found', 404
    return send_file(fpath, mimetype='audio/webm')

@app.route('/api/ticket-img/<fname>')
def serve_ticket_img(fname):
    import re as _re3
    if not _re3.match(r'^[a-zA-Z0-9_\-]+\.(jpg|jpeg|png|gif|webp)$', fname, _re3.IGNORECASE):
        return 'not found', 404
    fpath = os.path.join(TK_IMG_DIR, fname)
    if not os.path.exists(fpath):
        return 'not found', 404
    ext = fname.rsplit('.', 1)[-1].lower()
    mime = {'jpg':'image/jpeg','jpeg':'image/jpeg','png':'image/png','gif':'image/gif','webp':'image/webp'}.get(ext,'image/jpeg')
    resp = make_response(send_file(fpath, mimetype=mime))
    resp.headers['Cache-Control'] = 'public, max-age=31536000'
    return resp

@app.route('/api/tickets/image', methods=['POST'])
def api_ticket_image():
    if 'user_id' not in session:
        return jsonify(ok=False, error='unauthorized'), 401
    data = freq.json or {}
    tid = data.get('ticket_id', '')
    image = data.get('image', '')
    caption = data.get('caption', '').strip()
    if not image or not tid:
        return jsonify(ok=False, error='missing data')
    if len(image) > 8_000_000:
        return jsonify(ok=False, error='too large')
    conn = get_db()
    t = conn.execute('SELECT * FROM tickets WHERE id=? AND user_id=?', (tid, session['user_id'])).fetchone()
    if not t:
        conn.close()
        return jsonify(ok=False, error='not found')
    import base64 as _b64
    ext = 'jpg'
    if 'image/png' in image[:50]: ext = 'png'
    elif 'image/gif' in image[:50]: ext = 'gif'
    elif 'image/webp' in image[:50]: ext = 'webp'
    if ',' in image: image = image.split(',', 1)[1]
    fname = f'ti_{tid}_{uuid.uuid4().hex[:8]}.{ext}'
    fpath = os.path.join(TK_IMG_DIR, fname)
    try:
        with open(fpath, 'wb') as f:
            f.write(_b64.b64decode(image))
    except:
        conn.close()
        return jsonify(ok=False, error='invalid image')
    img_url = f'/api/ticket-img/{fname}'
    conn.execute('INSERT INTO ticket_messages(ticket_id,sender,msg_type,voice_url,text) VALUES(?,?,?,?,?)',
                 (tid, 'user', 'image', img_url, caption))
    conn.execute('UPDATE tickets SET status=? WHERE id=?', ('waiting', tid))
    conn.commit()
    admins = conn.execute('SELECT id FROM users WHERE is_admin=1').fetchall()
    for a in admins:
        push_user_notif(a['id'], 'admin', f'صورة في تذكرة #TK-{tid}', f'من {session.get("user_name","مستخدم")}', 'message', goto=f'ticket:{tid}')
    conn.close()
    return jsonify(ok=True, img_url=img_url)

@app.route('/api/admin/tickets', methods=['POST'])
def api_admin_tickets():
    if 'user_id' not in session or not session.get('is_admin'):
        return jsonify(ok=False, error='unauthorized'), 401
    conn = get_db()
    rows = conn.execute('SELECT t.*, u.name as user_name, u.email as user_email FROM tickets t LEFT JOIN users u ON t.user_id=u.id ORDER BY t.created_at DESC').fetchall()
    result = []
    for t in rows:
        msgs = conn.execute('SELECT * FROM ticket_messages WHERE ticket_id=? ORDER BY created_at ASC', (t['id'],)).fetchall()
        clean_msgs = []
        for m in msgs:
            cm = {'from': m['sender'], 'text': m['text'], 'time': time.strftime('%d/%m %H:%M', time.localtime(m['created_at']))}
            if m['msg_type'] == 'voice':
                cm['type'] = 'voice'
                cm['url'] = m['voice_url']
                cm['duration'] = m['duration']
            elif m['msg_type'] == 'image':
                cm['type'] = 'image'
                cm['url'] = m['voice_url']
            clean_msgs.append(cm)
        result.append({
            'id': t['id'], 'uid': t['user_id'], 'subject': t['subject'],
            'category': t['category'], 'status': t['status'],
            'date': time.strftime('%d/%m %H:%M', time.localtime(t['created_at'])),
            'user_name': t['user_name'] or '', 'user_email': t['user_email'] or '',
            'messages': clean_msgs, 'msg_count': len(clean_msgs)
        })
    conn.close()
    return jsonify(ok=True, tickets=result)

