@app.route('/api/tickets/delete', methods=['POST'])
def api_user_ticket_delete():
    if 'user_id' not in session:
        return jsonify(ok=False), 401
    uid = session['user_id']
    data = freq.get_json() or {}
    ids = data.get('ids', [])
    if not ids:
        return jsonify(ok=False, msg='لا توجد تذاكر محددة')
    conn = get_db()
    count = 0
    for tid in ids:
        tk = conn.execute('SELECT id FROM tickets WHERE id=? AND user_id=? AND status=?', (tid, uid, 'closed')).fetchone()
        if tk:
            conn.execute('DELETE FROM ticket_messages WHERE ticket_id=?', (tid,))
            conn.execute('DELETE FROM tickets WHERE id=?', (tid,))
            count += 1
    conn.commit()
    conn.close()
    return jsonify(ok=True, deleted=count)

