@app.route('/api/recharge/history')
def api_recharge_history():
    if 'user_id' not in session:
        return jsonify(ok=False, error='unauthorized'), 401
    uid = session['user_id']
    conn = get_db()
    rows = conn.execute('SELECT * FROM recharge_requests WHERE user_id=? ORDER BY created_at DESC LIMIT 50', (uid,)).fetchall()
    result = []
    for r in rows:
        receipt_val = r['receipt'] or ''
        has_receipt = bool(receipt_val)
        receipt_short = receipt_val if (receipt_val and not receipt_val.startswith('data:image')) else ''
        result.append({
            'id': r['id'], 'amount': r['amount'], 'method': r['method'],
            'status': r['status'], 'date': time.strftime('%d/%m %H:%M', time.localtime(r['created_at'])),
            'full_date': time.strftime('%d/%m/%Y', time.localtime(r['created_at'])),
            'full_time': time.strftime('%H:%M', time.localtime(r['created_at'])),
            'receipt': receipt_short, 'has_receipt': has_receipt
        })
    conn.close()
    total = sum(r['amount'] for r in result if r['status'] == 'approved')
    return jsonify(ok=True, history=result, total=total)

