REFERRAL_COMMISSION = 5
REFERRAL_MIN_WITHDRAW = 1.0

def _get_or_create_referral(user_id):
    conn = get_db()
    ref = conn.execute('SELECT * FROM referrals WHERE user_id=?', (user_id,)).fetchone()
    if not ref:
        code = 'FC' + uuid.uuid4().hex[:6].upper()
        conn.execute('INSERT INTO referrals(user_id,code) VALUES(?,?)', (user_id, code))
        conn.commit()
        ref = conn.execute('SELECT * FROM referrals WHERE user_id=?', (user_id,)).fetchone()
    conn.close()
    return ref

@app.route('/api/referral', methods=['POST'])
def api_referral():
    if 'user_id' not in session:
        return jsonify(ok=False), 401
    uid = session['user_id']
    ref = _get_or_create_referral(uid)
    conn = get_db()
    history = conn.execute('SELECT * FROM referral_history WHERE referrer_id=? ORDER BY created_at DESC LIMIT 10', (uid,)).fetchall()
    conn.close()
    hist = [{'amount': round(h['amount'], 4), 'from_order': h['from_order'],
             'time': time.strftime('%d/%m %H:%M', time.localtime(h['created_at']))} for h in history]
    return jsonify(ok=True, referral={
        'code': ref['code'], 'count': ref['ref_count'],
        'earnings': round(ref['earnings'], 2), 'pending': round(ref['pending'], 2),
        'commission': REFERRAL_COMMISSION, 'min_withdraw': REFERRAL_MIN_WITHDRAW,
        'link': f'https://{DOMAIN}/app?ref={ref["code"]}',
        'history': hist
    })

@app.route('/api/referral/apply', methods=['POST'])
def api_referral_apply():
    if 'user_id' not in session:
        return jsonify(ok=False), 401
    uid = session['user_id']
    data = freq.json or {}
    code = str(data.get('code', '')).strip().upper()
    if not code:
        return jsonify(ok=False, error='أدخل كود الإحالة')
    my_ref = _get_or_create_referral(uid)
    if my_ref['referred_by']:
        return jsonify(ok=False, error='لديك إحالة مسبقاً')
    if my_ref['code'] == code:
        return jsonify(ok=False, error='لا يمكنك إحالة نفسك')
    conn = get_db()
    referrer = conn.execute('SELECT * FROM referrals WHERE code=?', (code,)).fetchone()
    if not referrer:
        conn.close()
        return jsonify(ok=False, error='كود إحالة غير صالح')
    conn.execute('UPDATE referrals SET referred_by=? WHERE user_id=?', (referrer['user_id'], uid))
    conn.execute('UPDATE referrals SET ref_count=ref_count+1 WHERE user_id=?', (referrer['user_id'],))
    conn.commit()
    conn.close()
    return jsonify(ok=True)

@app.route('/api/referral/withdraw', methods=['POST'])
def api_referral_withdraw():
    if 'user_id' not in session:
        return jsonify(ok=False), 401
    uid = session['user_id']
    ref = _get_or_create_referral(uid)
    pending = ref['pending']
    if pending < REFERRAL_MIN_WITHDRAW:
        return jsonify(ok=False, error=f'الحد الأدنى للسحب ${REFERRAL_MIN_WITHDRAW}')
    conn = get_db()
    conn.execute('UPDATE referrals SET earnings=earnings+?, pending=0 WHERE user_id=?', (pending, uid))
    conn.execute('UPDATE users SET balance=balance+? WHERE id=?', (pending, uid))
    conn.commit()
    new_bal = conn.execute('SELECT balance FROM users WHERE id=?', (uid,)).fetchone()['balance']
    conn.close()
    return jsonify(ok=True, amount=round(pending, 2), balance=round(new_bal, 2))

MARKUP_RATE = 1.5

@app.route('/api/admin/profits', methods=['POST'])
def api_admin_profits():
    if 'user_id' not in session or not session.get('is_admin'):
        return jsonify(ok=False), 403
    conn = get_db()
    rows = conn.execute('SELECT * FROM orders').fetchall()
    conn.close()
    total_revenue = 0
    total_provider = 0
    total_orders = 0
    for o in rows:
        c = float(o['charge'] or 0)
        total_revenue += c
        total_orders += 1
        total_provider += round(c / MARKUP_RATE, 4) if MARKUP_RATE > 0 else c
    profit = round(total_revenue - total_provider, 2)
    margin = round((profit / total_revenue * 100), 1) if total_revenue > 0 else 0
    avg_profit = round(profit / total_orders, 2) if total_orders > 0 else 0
    return jsonify(ok=True, revenue=round(total_revenue, 2), provider_cost=round(total_provider, 2),
                   profit=profit, margin=margin, total_orders=total_orders,
                   avg_profit=avg_profit, markup=MARKUP_RATE)

