def push_user_notif(user_id, ntype, title, text, icon='bell', goto=''):
    try:
        conn = get_db()
        nid = uuid.uuid4().hex[:8]
        conn.execute('INSERT INTO notifications(id,user_id,type,title,text,icon,goto) VALUES(?,?,?,?,?,?,?)',
                     (nid, user_id, ntype, title, text, icon, goto))
        conn.commit()
        conn.execute('''DELETE FROM notifications WHERE id IN (
            SELECT id FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT -1 OFFSET 50
        )''', (user_id,))
        conn.commit()
        conn.close()
    except Exception as e:
        print(f" [notif] DB write failed uid={user_id} type={ntype}: {e}")
        return
    try:
        send_push(user_id, title, text)
    except Exception as e:
        print(f" [notif] send_push raised uid={user_id}: {e}")

