def _add_referral_commission(user_id, order_id, cost):
    pass
    try:
        conn = get_db()
        ref = conn.execute('SELECT * FROM referrals WHERE user_id=?', (user_id,)).fetchone()
        if ref and ref['referred_by']:
            referrer_ref = conn.execute('SELECT * FROM referrals WHERE user_id=?', (ref['referred_by'],)).fetchone()
            if referrer_ref:
                commission = round(cost * REFERRAL_COMMISSION / 100, 4)
                if commission > 0:
                    conn.execute('UPDATE referrals SET pending=pending+? WHERE user_id=?', (commission, ref['referred_by']))
                    conn.execute('INSERT INTO referral_history(referrer_id,amount,from_order) VALUES(?,?,?)',
                                 (ref['referred_by'], commission, order_id))
                    conn.commit()
        conn.close()
    except:
        pass

@app.route('/api/admin/referral', methods=['POST'])
def api_admin_referral():
    if 'user_id' not in session or not session.get('is_admin'):
        return jsonify(ok=False, error='unauthorized'), 401
    conn = get_db()
    total_referrals = conn.execute('SELECT COALESCE(SUM(ref_count),0) FROM referrals').fetchone()[0]
    total_earnings = conn.execute('SELECT COALESCE(SUM(earnings),0) FROM referrals').fetchone()[0]
    total_pending = conn.execute('SELECT COALESCE(SUM(pending),0) FROM referrals').fetchone()[0]
    total_users = conn.execute('SELECT COUNT(*) FROM referrals').fetchone()[0]
    top_rows = conn.execute('''
        SELECT r.*, u.name as user_name, u.email as user_email
        FROM referrals r LEFT JOIN users u ON r.user_id=u.id
        WHERE r.ref_count > 0
        ORDER BY r.ref_count DESC LIMIT 10
    ''').fetchall()
    top = []
    for t in top_rows:
        top.append({
            'uid': t['user_id'], 'name': t['user_name'] or '', 'email': t['user_email'] or '',
            'code': t['code'], 'count': t['ref_count'],
            'earnings': round(t['earnings'], 2), 'pending': round(t['pending'], 2)
        })
    conn.close()
    return jsonify(ok=True, commission=REFERRAL_COMMISSION, min_withdraw=REFERRAL_MIN_WITHDRAW,
                   total_referrals=total_referrals, total_earnings=round(total_earnings, 2),
                   total_pending=round(total_pending, 2), total_users=total_users, top=top)

