@app.route('/api/admin/custom_services/edit', methods=['POST'])
def api_admin_cs_edit():
    if 'user_id' not in session:
        return jsonify(ok=False), 401
    conn = get_db()
    u = conn.execute('SELECT is_admin FROM users WHERE id=?', (session['user_id'],)).fetchone()
    if not u or not u['is_admin']:
        conn.close()
        return jsonify(ok=False), 403
    data = freq.get_json() or {}
    sid = data.get('id', '')
    svc = conn.execute('SELECT * FROM custom_services WHERE id=?', (sid,)).fetchone()
    if not svc:
        conn.close()
        return jsonify(ok=False, error='not found')
    sets = []
    vals = []
    for k in ('name', 'icon', 'color', 'image'):
        if k in data:
            sets.append(f'{k}=?')
            vals.append(data[k])
    if 'desc' in data:
        sets.append('desc_text=?')
        vals.append(data['desc'])
    if 'active' in data:
        sets.append('active=?')
        vals.append(1 if data['active'] else 0)
    if svc['type'] == 'subscription' and 'packages' in data:
        sets.append('packages=?')
        vals.append(json.dumps(data['packages'], ensure_ascii=False))
    elif svc['type'] == 'social':
        for k in ('rate', 'min', 'max'):
            if k in data:
                col = 'min_qty' if k == 'min' else ('max_qty' if k == 'max' else k)
                sets.append(f'{col}=?')
                vals.append(float(data[k]) if k == 'rate' else int(data[k]))
    if sets:
        vals.append(sid)
        conn.execute(f'UPDATE custom_services SET {",".join(sets)} WHERE id=?', vals)
        conn.commit()
    conn.close()
    return jsonify(ok=True)

