@app.route('/api/custom_order', methods=['POST'])
def api_custom_order():
    if 'user_id' not in session:
        return jsonify(ok=False, error='unauthorized'), 401
    data = freq.get_json() or {}
    uid = session['user_id']
    sid = data.get('service_id', '')
    conn = get_db()
    svc_row = conn.execute('SELECT * FROM custom_services WHERE id=? AND active=1', (sid,)).fetchone()
    if not svc_row:
        conn.close()
        return jsonify(ok=False, error='service_not_found')
    svc = dict(svc_row)
    try:
        svc['packages'] = json.loads(svc.get('packages') or '[]')
    except:
        svc['packages'] = []
    user = conn.execute('SELECT * FROM users WHERE id=?', (uid,)).fetchone()
    oid = f"CO-{int(time.time())}-{secrets.token_hex(2)}"

    if svc['type'] == 'subscription':
        pkg_index = int(data.get('package_index', 0))
        packages = svc.get('packages', [])
        if pkg_index < 0 or pkg_index >= len(packages):
            conn.close()
            return jsonify(ok=False, error='invalid_package')
        pkg = packages[pkg_index]
        cost = float(pkg.get('price', 0))
        bal = float(user['balance'])
        if not user['is_admin'] and bal < cost:
            conn.close()
            return jsonify(ok=False, error='insufficient_balance', balance=bal, cost=cost)
        if not user['is_admin']:
            conn.execute('UPDATE users SET balance=balance-? WHERE id=?', (cost, uid))
        conn.execute('INSERT INTO custom_orders(id,user_id,service_id,service_name,type,package,cost,status) VALUES(?,?,?,?,?,?,?,?)',
                     (oid, uid, sid, svc['name'], 'subscription', pkg.get('name', ''), cost, 'pending'))
        tk_subject = f"طلب اشتراك: {svc['name']} — {pkg.get('name','')}"
        conn.execute('INSERT INTO tickets(user_id,subject,category,status) VALUES(?,?,?,?)',
                     (uid, tk_subject, ' طلب اشتراك', 'open'))
        tk_id = conn.execute('SELECT last_insert_rowid()').fetchone()[0]
        sys_msg = f"🎫 طلب اشتراك جديد\n\n{svc.get('icon','')} {svc['name']}\n الباقة: {pkg.get('name','')}\n السعر: ${cost:.2f}\n⏱ المدة: {pkg.get('duration','')}\n\nبانتظار الإدارة لإرسال التفاصيل..."
        conn.execute('INSERT INTO ticket_messages(ticket_id,sender,text) VALUES(?,?,?)', (tk_id, 'system', sys_msg))
        conn.commit()
        new_bal = conn.execute('SELECT balance FROM users WHERE id=?', (uid,)).fetchone()['balance']
        nid = str(uuid.uuid4())[:8]
        conn.execute('INSERT INTO notifications(id,user_id,type,title,text,icon) VALUES(?,?,?,?,?,?)',
                     (nid, uid, 'order', 'تم تقديم طلب اشتراك! ', f"{svc['name']} — {pkg.get('name','')} — ${cost:.2f}", 'order'))
        conn.commit()
        conn.close()
        return jsonify(ok=True, order={'id': oid, 'service_name': svc['name'], 'package': pkg.get('name',''), 'cost': cost, 'status': 'pending'},
                       ticket_id=tk_id, balance=round(new_bal, 4))
    else:
        link = (data.get('link') or '').strip()
        qty = int(data.get('quantity', 0))
        comments = (data.get('comments') or '').strip()
        rate = float(svc.get('rate', 0))
        mn, mx = int(svc.get('min_qty', 0)), int(svc.get('max_qty', 0))
        if not link.startswith('http'):
            conn.close()
            return jsonify(ok=False, error='invalid_link')
        if qty < mn or qty > mx:
            conn.close()
            return jsonify(ok=False, error='quantity_out_of_range', min=mn, max=mx)
        cost = round((rate * qty) / 1000.0, 4)
        bal = float(user['balance'])
        if not user['is_admin'] and bal < cost:
            conn.close()
            return jsonify(ok=False, error='insufficient_balance', balance=bal, cost=cost)
        if not user['is_admin']:
            conn.execute('UPDATE users SET balance=balance-? WHERE id=?', (cost, uid))
        conn.execute('INSERT INTO custom_orders(id,user_id,service_id,service_name,type,link,quantity,comments,cost,status) VALUES(?,?,?,?,?,?,?,?,?,?)',
                     (oid, uid, sid, svc['name'], 'social', link, qty, comments, cost, 'pending'))
        tk_subject = f"طلب خدمة: {svc['name']} — الكمية: {qty}"
        conn.execute('INSERT INTO tickets(user_id,subject,category,status) VALUES(?,?,?,?)',
                     (uid, tk_subject, 'طلب خدمة', 'open'))
        tk_id = conn.execute('SELECT last_insert_rowid()').fetchone()[0]
        sys_msg = f"🎫 طلب خدمة جديد\n\n{svc['name']}\n🔗 الرابط: {link}\n📊 الكمية: {qty}\n💰 السعر: ${cost:.4f}"
        if comments:
            sys_msg += f"\n📝 ملاحظات: {comments}"
        sys_msg += "\n\nبانتظار الإدارة لتنفيذ الطلب..."
        conn.execute('INSERT INTO ticket_messages(ticket_id,sender,text) VALUES(?,?,?)', (tk_id, 'system', sys_msg))
        conn.commit()
        new_bal = conn.execute('SELECT balance FROM users WHERE id=?', (uid,)).fetchone()['balance']
        nid = str(uuid.uuid4())[:8]
        conn.execute('INSERT INTO notifications(id,user_id,type,title,text,icon) VALUES(?,?,?,?,?,?)',
                     (nid, uid, 'order', 'تم تقديم طلبك! ', f"{svc['name']} — الكمية: {qty} — ${cost:.4f}", 'order'))
        conn.commit()
        conn.close()
        return jsonify(ok=True, order={'id': oid, 'service_name': svc['name'], 'qty': qty, 'cost': cost, 'status': 'pending'},
                       ticket_id=tk_id, balance=round(new_bal, 4))

