@app.route('/api/admin/custom_orders/update', methods=['POST'])
def api_admin_custom_order_update():
    if 'user_id' not in session:
        return jsonify(ok=False), 401
    conn = get_db()
    u = conn.execute('SELECT is_admin FROM users WHERE id=?', (session['user_id'],)).fetchone()
    if not u or not u['is_admin']:
        conn.close()
        return jsonify(ok=False), 403
    data = freq.get_json() or {}
    oid = data.get('order_id', '')
    status = data.get('status', '')
    order = conn.execute('SELECT * FROM custom_orders WHERE id=?', (oid,)).fetchone()
    if not order:
        conn.close()
        return jsonify(ok=False, error='not found')
    conn.execute('UPDATE custom_orders SET status=? WHERE id=?', (status, oid))
    co_uid = order['user_id']
    if status == 'canceled' and float(order['cost']) > 0 and not order['refunded']:
        conn.execute('UPDATE users SET balance=balance+? WHERE id=?', (float(order['cost']), co_uid))
        conn.execute('UPDATE custom_orders SET refunded=1 WHERE id=?', (oid,))
        nid = str(uuid.uuid4())[:8]
        conn.execute('INSERT INTO notifications(id,user_id,type,title,text,icon) VALUES(?,?,?,?,?,?)',
                     (nid, co_uid, 'system', 'تم إلغاء طلبك المخصص ', f"{order['service_name']} — تم استرجاع ${float(order['cost']):.2f}", 'wallet'))
    elif status == 'completed':
        nid = str(uuid.uuid4())[:8]
        conn.execute('INSERT INTO notifications(id,user_id,type,title,text,icon) VALUES(?,?,?,?,?,?)',
                     (nid, co_uid, 'order', 'تم اكتمال طلبك! ', order['service_name'], 'done'))
    elif status == 'processing':
        nid = str(uuid.uuid4())[:8]
        conn.execute('INSERT INTO notifications(id,user_id,type,title,text,icon) VALUES(?,?,?,?,?,?)',
                     (nid, co_uid, 'system', 'طلبك قيد التنفيذ ⚙', f"{order['service_name']} — الإدارة تعمل على طلبك", 'order'))
    conn.commit()
    conn.close()
    return jsonify(ok=True)

LOGO_DIR = '/root/fc_logo'
os.makedirs(LOGO_DIR, exist_ok=True)

