@app.route('/api/admin/site-settings')
def api_admin_site_settings_get():
    if not _admin_check():
        return jsonify(ok=False), 403
    keys = ['site_name','site_name_color','smtp_enabled','smtp_host','smtp_port','smtp_tls','smtp_email','smtp_password','smtp_sender_name',
            'backup_enabled','backup_interval','tg_bot_token','tg_chat_id','provider_api_url','provider_api_key',
            'rate_IQD','rate_EUR','rate_SAR','rate_AED','rate_TRY','google_client_id',
            'support_whatsapp','site_terms','site_privacy','skip_email_verify',
            'deepseek_api_key','deepseek_model','ai_logo']
    out = {}
    conn = get_db()
    for k in keys:
        row = conn.execute('SELECT value FROM site_settings WHERE key=?', (k,)).fetchone()
        out[k] = row['value'] if row else ''
    conn.close()
    if not out['site_name']: out['site_name'] = 'fastcrand'
    if not out['smtp_host']: out['smtp_host'] = 'smtp.gmail.com'
    if not out['smtp_port']: out['smtp_port'] = '587'
    if not out['smtp_tls']: out['smtp_tls'] = 'TLS'
    if not out['provider_api_url']: out['provider_api_url'] = SMM_API_URL
    if not out['provider_api_key']: out['provider_api_key'] = SMM_API_KEY
    if not out['rate_IQD']: out['rate_IQD'] = '1500'
    if not out['rate_EUR']: out['rate_EUR'] = '0.92'
    if not out['rate_SAR']: out['rate_SAR'] = '3.75'
    if not out['rate_AED']: out['rate_AED'] = '3.67'
    if not out['rate_TRY']: out['rate_TRY'] = '38.5'
    out['has_logo'] = os.path.exists(os.path.join(LOGO_DIR, 'logo.png')) or os.path.exists(os.path.join(LOGO_DIR, 'logo.jpg'))
    out['has_pwa_icon'] = os.path.exists(os.path.join(PWA_ICON_DIR, 'icon-192.png'))
    out['pwa_icon_version'] = get_setting('pwa_icon_version', '2')
    return jsonify(ok=True, settings=out)

