@app.route('/api/admin/upload-logo', methods=['POST'])
def api_admin_upload_logo():
    if not _admin_check():
        return jsonify(ok=False), 403
    f = freq.files.get('logo')
    if not f:
        return jsonify(ok=False, error='no file')
    ext = f.filename.rsplit('.', 1)[-1].lower() if '.' in f.filename else 'png'
    if ext not in ('png', 'jpg', 'jpeg', 'svg', 'webp'):
        return jsonify(ok=False, error='invalid format')
    for old in glob.glob(os.path.join(LOGO_DIR, 'logo.*')):
        os.remove(old)
    path = os.path.join(LOGO_DIR, f'logo.{ext}')
    f.save(path)
    return jsonify(ok=True, url=f'/api/admin/logo?t={int(time.time())}')

