@app.route('/api/admin/upload-pwa-icon', methods=['POST'])
def api_admin_upload_pwa_icon():
    pass
    if not _admin_check():
        return jsonify(ok=False), 403
    f = freq.files.get('icon')
    if not f:
        return jsonify(ok=False, error='no file')
    ext = f.filename.rsplit('.', 1)[-1].lower() if '.' in f.filename else ''
    if ext not in ('png', 'jpg', 'jpeg', 'webp'):
        return jsonify(ok=False, error='invalid format — PNG/JPG/WEBP فقط')
    try:
        raw = f.read()
    except Exception as e:
        return jsonify(ok=False, error=f'تعذّر قراءة الملف: {e}')
    if len(raw) > 5 * 1024 * 1024:
        return jsonify(ok=False, error='الملف كبير جداً — الحد 5MB')
    if len(raw) < 32:
        return jsonify(ok=False, error='الملف فارغ أو تالف')

    try:
        from PIL import Image
        has_pillow = True
    except ImportError:
        has_pillow = False

    try:
        if has_pillow:
            img = Image.open(io.BytesIO(raw))
            if img.mode not in ('RGBA', 'RGB'):
                img = img.convert('RGBA')
            w, h = img.size
            if w != h:
                m = min(w, h)
                left = (w - m) // 2
                top = (h - m) // 2
                img = img.crop((left, top, left + m, top + m))
            for sz in (192, 512):
                resized = img.resize((sz, sz), Image.LANCZOS)
                if resized.mode != 'RGBA':
                    resized = resized.convert('RGBA')
                out_path = os.path.join(PWA_ICON_DIR, f'icon-{sz}.png')
                resized.save(out_path, 'PNG', optimize=True)
        else:
            pass
            if ext != 'png':
                return jsonify(
                    ok=False,
                    error='مكتبة Pillow غير مثبّتة على السيرفر. بدونها يُقبل PNG فقط. شغّل: pip3 install Pillow --break-system-packages'
                )
            if not raw.startswith(b'\x89PNG\r\n\x1a\n'):
                return jsonify(ok=False, error='الملف ليس PNG صالح')
            for sz in (192, 512):
                out_path = os.path.join(PWA_ICON_DIR, f'icon-{sz}.png')
                with open(out_path, 'wb') as out_f:
                    out_f.write(raw)

        cur_v = int(get_setting('pwa_icon_version', '2') or '2')
        set_setting('pwa_icon_version', str(cur_v + 1))
        return jsonify(
            ok=True,
            version=cur_v + 1,
            ts=int(time.time()),
            warning=None if has_pillow else 'تم الرفع بدون تصغير (Pillow غير مثبّت). يُفضّل تثبيتها للحصول على أفضل جودة.'
        )
    except Exception as e:
        return jsonify(ok=False, error=str(e))

