@app.route('/api/admin/smtp-test', methods=['POST'])
def api_admin_smtp_test():
    if not _admin_check():
        return jsonify(ok=False), 403
    data = freq.get_json() or {}
    host = data.get('host', 'smtp.gmail.com')
    port = int(data.get('port', 587))
    tls = data.get('tls', 'TLS')
    email = data.get('email', '')
    password = data.get('password', '')
    sender_name = data.get('sender_name', 'fastcrand')
    _sname = get_setting('site_name', 'fastcrand')
    try:
        msg = MIMEMultipart()
        msg['From'] = f'{sender_name} <{email}>'
        msg['To'] = email
        msg['Subject'] = f'تجربة SMTP — {_sname}'
        msg.attach(MIMEText(f'هذه رسالة تجريبية من {_sname} لفحص إعدادات SMTP ', 'plain', 'utf-8'))
        if tls == 'SSL':
            server = smtplib.SMTP_SSL(host, port, timeout=10)
        else:
            server = smtplib.SMTP(host, port, timeout=10)
            if tls == 'TLS':
                server.starttls()
        server.login(email, password)
        server.send_message(msg)
        server.quit()
        return jsonify(ok=True)
    except Exception as e:
        return jsonify(ok=False, error=str(e))

