@app.route('/api/admin/levels')
def api_admin_levels():
    if not _admin_check(): return jsonify(ok=False), 403
    conn = get_db()
    rows = conn.execute('SELECT * FROM levels ORDER BY min_spent ASC').fetchall()
    spent_rows = conn.execute("SELECT user_id, COALESCE(SUM(CAST(charge AS REAL)),0) as total FROM orders WHERE status='Completed' GROUP BY user_id").fetchall()
    all_users = conn.execute("SELECT id FROM users").fetchall()
    user_spent = {r['user_id']: float(r['total']) for r in spent_rows}
    for u in all_users:
        if u['id'] not in user_spent:
            user_spent[u['id']] = 0.0
    conn.close()
    lvs = [dict(r) for r in rows]
    for lv in lvs:
        lv['benefits'] = [b.strip() for b in (lv['benefits'] or '').split('\n') if b.strip()]
        lv['users'] = 0
    active_lvs = sorted([l for l in lvs if l.get('active')], key=lambda x: float(x['min_spent']))
    for uid, total in user_spent.items():
        matched = None
        for lv in active_lvs:
            if total >= float(lv['min_spent']):
                matched = lv
        if matched:
            matched['users'] += 1
    return jsonify(ok=True, levels=lvs)

