@app.route('/api/admin/order_lookup', methods=['POST'])
def api_admin_order_lookup():
    if not _admin_check():
        return jsonify(ok=False, error='unauthorized'), 403
    data = freq.get_json() or {}
    order_id = str(data.get('order_id', '')).strip()
    if not order_id:
        return jsonify(ok=False, error='أدخل رقم الطلب أو رقم العرض')
    conn = get_db()
    row = conn.execute('''SELECT o.*, u.username, u.name, u.public_id
                          FROM orders o LEFT JOIN users u ON o.user_id = u.id
                          WHERE o.order_id=? OR o.display_id=? LIMIT 1''', (order_id, order_id)).fetchone()
    local = {}
    owner = {}
    real_provider_order_id = order_id
    if row:
        real_provider_order_id = str(row['order_id'] or order_id)
        local = {
            'service': row['service_name'] or '',
            'service_id': str(row['service'] or ''),
            'qty': row['quantity'] or 0,
            'link': row['link'] or '',
            'cost': float(row['site_charge'] or 0),
            'provider_cost': float(row['charge'] or 0) if row['charge'] else 0,
            'date': row['created_at'] if 'created_at' in row.keys() else '',
            'status': row['status'] or '',
            'display_id': row['display_id'] or '',
        }
        owner = {
            'uid': str(row['user_id'] or ''),
            'name': row['name'] or row['username'] or '',
            'public_id': row['public_id'] or '',
        }
    conn.close()
    provider = {}
    try:
        _ord_pid = 0
        if row:
            try: _ord_pid = int(row['provider_id'] or 0)
            except: _ord_pid = 0
        if _ord_pid:
            api_url, api_key, _ = get_provider_api(_ord_pid)
        else:
            api_url, api_key, _ = get_provider_api()
        rr = requests.post(api_url, data={'key': api_key, 'action': 'status', 'order': real_provider_order_id}, timeout=12)
        rec = rr.json()
        if isinstance(rec, dict):
            provider = rec
    except:
        pass
    if not provider and not local:
        return jsonify(ok=False, error='الطلب غير موجود')
    return jsonify(ok=True, provider=provider, local=local, owner=owner)

@app.route('/api/admin/provider-categories')
def api_admin_provider_categories():
    pass
    if not _admin_check():
        return jsonify(ok=False), 403
    try:
        api_url, api_key, _prov_id = get_provider_api()
        r = requests.post(api_url, data={'key': api_key, 'action': 'services'}, timeout=20)
        svcs = r.json()
        if not isinstance(svcs, list):
            return jsonify(ok=False, error='Invalid API response')
        platforms = {}
        for s in svcs:
            cat = s.get('category', '')
            name = s.get('name', '')
            sid = str(s.get('service', ''))
            rate = s.get('rate', '0')
            platform = _detect_platform(cat, name)
            if platform not in platforms:
                platforms[platform] = {'categories': {}, 'count': 0}
            if cat not in platforms[platform]['categories']:
                platforms[platform]['categories'][cat] = 0
            platforms[platform]['categories'][cat] += 1
            platforms[platform]['count'] += 1
        return jsonify(ok=True, platforms=platforms, total=len(svcs))
    except Exception as e:
        return jsonify(ok=False, error=str(e))

@app.route('/api/admin/provider-save', methods=['POST'])
def api_admin_provider_save():
    pass
    if not _admin_check():
        return jsonify(ok=False), 403
    data = freq.get_json() or {}
    api_url = data.get('api_url', '').strip()
    api_key = data.get('api_key', '').strip()
    if not api_url or not api_key:
        return jsonify(ok=False, error='يجب إدخال الرابط والمفتاح')
    conn = get_db()
    conn.execute('INSERT OR REPLACE INTO site_settings(key,value) VALUES(?,?)', ('provider_api_url', api_url))
