    defp = conn.execute('SELECT id FROM providers WHERE is_default=1 LIMIT 1').fetchone()
    if defp:
        conn.execute('UPDATE providers SET api_url=?, api_key=? WHERE id=?', (api_url, api_key, defp['id']))
    conn.commit()
    conn.close()
    global _services_cache
    _services_cache['data'] = None
    _services_cache['time'] = 0
    return jsonify(ok=True)

