@app.route('/api/admin/coupons', methods=['POST'])
def api_admin_coupons_create():
    if not _admin_check():
        return jsonify(ok=False), 403
    data = freq.get_json() or {}
    code = data.get('code', '').strip().upper()
    amount = float(data.get('amount', 0))
    max_uses = int(data.get('max_uses', 1))
    expires_at = data.get('expires_at', '')
    if not code or amount <= 0:
        return jsonify(ok=False, error='بيانات ناقصة')
    cid = str(uuid.uuid4())[:8]
    conn = get_db()
    try:
        conn.execute('INSERT INTO coupons(id,code,amount,max_uses,expires_at) VALUES(?,?,?,?,?)',
                     (cid, code, amount, max_uses, expires_at))
        conn.commit()
    except:
        conn.close()
        return jsonify(ok=False, error='الكود موجود مسبقاً')
    notify_all = data.get('notify_all', False)
    if notify_all:
        users = conn.execute('SELECT id FROM users WHERE is_admin=0').fetchall()
        for u in users:
            nid = str(uuid.uuid4())[:8]
            conn.execute('INSERT INTO notifications(id,user_id,type,title,text,icon) VALUES(?,?,?,?,?,?)',
                         (nid, u['id'], 'system', 'كوبون هدية جديد ', f'استخدم الكود {code} واحصل على ${amount:.2f} رصيد مجاني!', 'gift'))
        conn.commit()
    conn.close()
    return jsonify(ok=True, id=cid)

