@app.route('/api/redeem-coupon', methods=['POST'])
def api_redeem_coupon():
    if 'user_id' not in session:
        return jsonify(ok=False, error='سجل دخولك أولاً'), 401
    data = freq.get_json() or {}
    code = data.get('code', '').strip().upper()
    if not code:
        return jsonify(ok=False, error='أدخل كود الكوبون')
    conn = get_db()
    coupon = conn.execute('SELECT * FROM coupons WHERE code=? AND active=1', (code,)).fetchone()
    if not coupon:
        conn.close()
        return jsonify(ok=False, error='كود غير صالح أو منتهي')
    if coupon['expires_at'] and coupon['expires_at'] < time.strftime('%Y-%m-%d'):
        conn.close()
        return jsonify(ok=False, error='الكوبون منتهي الصلاحية')
    if coupon['used'] >= coupon['max_uses']:
        conn.close()
        return jsonify(ok=False, error='تم استخدام الكوبون بالكامل')
    used = conn.execute('SELECT id FROM coupon_uses WHERE coupon_id=? AND user_id=?', (coupon['id'], session['user_id'])).fetchone()
    if used:
        conn.close()
        return jsonify(ok=False, error='لقد استخدمت هذا الكوبون مسبقاً')
    conn.execute('UPDATE users SET balance=balance+? WHERE id=?', (coupon['amount'], session['user_id']))
    conn.execute('UPDATE coupons SET used=used+1 WHERE id=?', (coupon['id'],))
    conn.execute('INSERT INTO coupon_uses(coupon_id,user_id) VALUES(?,?)', (coupon['id'], session['user_id']))
    nid = str(uuid.uuid4())[:8]
    conn.execute('INSERT INTO notifications(id,user_id,type,title,text,icon) VALUES(?,?,?,?,?,?)',
                 (nid, session['user_id'], 'system', f'كوبون هدية ', f'تم إضافة ${coupon["amount"]:.2f} لرصيدك بكوبون {code}', 'wallet'))
    conn.commit()
    new_bal = conn.execute('SELECT balance FROM users WHERE id=?', (session['user_id'],)).fetchone()['balance']
    conn.close()
    return jsonify(ok=True, amount=coupon['amount'], balance=new_bal)

@app.route('/api/admin/daily-gift')
def api_admin_daily_gift_get():
    if 'user_id' not in session: return jsonify(ok=False), 401
    conn = get_db()
    u = conn.execute('SELECT role FROM users WHERE id=?', (session['user_id'],)).fetchone()
    if not u or u['role'] != 'admin':
        conn.close(); return jsonify(ok=False), 403
    dg_amount = _get_setting('daily_gift_amount', '0')
    dg_code = _get_setting('daily_gift_code', '')
    dg_date = _get_setting('daily_gift_date', '')
    dg_max = _get_setting('daily_gift_max_uses', '100')
    dg_active = _get_setting('daily_gift_active', '0')
    conn.close()
    return jsonify(ok=True, amount=dg_amount, code=dg_code, date=dg_date, max_uses=dg_max, active=dg_active)

@app.route('/api/admin/daily-gift', methods=['POST'])
def api_admin_daily_gift_save():
    if 'user_id' not in session: return jsonify(ok=False), 401
    conn = get_db()
    u = conn.execute('SELECT role FROM users WHERE id=?', (session['user_id'],)).fetchone()
    if not u or u['role'] != 'admin':
        conn.close(); return jsonify(ok=False), 403
    data = freq.get_json() or {}
    amount = float(data.get('amount', 0))
    max_uses = int(data.get('max_uses', 100))
    notify = data.get('notify', False)
    if amount <= 0:
        conn.close(); return jsonify(ok=False, error='حدد مبلغ صحيح')
    code = 'DAILY' + str(int(time.time()))[-6:]
    today = time.strftime('%Y-%m-%d')
    expires = time.strftime('%Y-%m-%d', time.localtime(time.time() + 86400))
    cid = str(uuid.uuid4())[:8]
    conn.execute('INSERT INTO coupons(id,code,amount,max_uses,expires_at) VALUES(?,?,?,?,?)',
                 (cid, code, amount, max_uses, expires))
    _set_setting('daily_gift_amount', str(amount))
    _set_setting('daily_gift_code', code)
    _set_setting('daily_gift_date', today)
    _set_setting('daily_gift_max_uses', str(max_uses))
    _set_setting('daily_gift_active', '1')
    if notify:
        users = conn.execute('SELECT id FROM users WHERE role!="admin"').fetchall()
        for usr in users:
            nid = str(uuid.uuid4())[:8]
            conn.execute('INSERT INTO notifications(id,user_id,type,title,text,icon) VALUES(?,?,?,?,?,?)',
                         (nid, usr['id'], 'system', 'هدية يومية جديدة!', f'استخدم الكود {code} واحصل على ${amount:.2f} رصيد مجاني!', 'gift'))
    conn.commit()
    conn.close()
    return jsonify(ok=True, code=code)

@app.route('/api/daily-gift-code')
def api_daily_gift_code():
    if 'user_id' not in session: return jsonify(ok=False), 401
    active = _get_setting('daily_gift_active', '0')
    if active != '1': return jsonify(ok=True, active=False)
    code = _get_setting('daily_gift_code', '')
    amount = _get_setting('daily_gift_amount', '0')
    dg_date = _get_setting('daily_gift_date', '')
    today = time.strftime('%Y-%m-%d')
    if dg_date != today: return jsonify(ok=True, active=False)
    return jsonify(ok=True, active=True, code=code, amount=amount)

@app.route('/api/reviews')
def api_get_reviews():
    conn = get_db()
    day_seed = int(time.strftime('%Y%m%d'))
    rows = conn.execute('SELECT id,user_name,stars,text,created_at FROM reviews WHERE approved=1 ORDER BY id').fetchall()
    conn.close()
    reviews = [dict(r) for r in rows]
    if len(reviews) > 4:
        import random
        rng = random.Random(day_seed)
        rng.shuffle(reviews)
        reviews = reviews[:4]
    elif len(reviews) > 0:
        reviews = reviews[:4]
    all_conn = get_db()
    stats = all_conn.execute('SELECT COUNT(*) as cnt, AVG(stars) as avg_stars FROM reviews WHERE approved=1').fetchone()
    all_conn.close()
    total = stats['cnt'] if stats else 0
    avg = round(stats['avg_stars'], 1) if stats and stats['avg_stars'] else 0
    dist = {5:0,4:0,3:0,2:0,1:0}
    if total > 0:
        dc = get_db()
        for s in range(1,6):
            c = dc.execute('SELECT COUNT(*) as c FROM reviews WHERE approved=1 AND stars=?',(s,)).fetchone()
            dist[s] = round((c['c']/total)*100) if c else 0
        dc.close()
    return jsonify(ok=True, reviews=reviews, total=total, avg=avg, dist=dist)

@app.route('/api/reviews', methods=['POST'])
def api_submit_review():
    if 'user_id' not in session: return jsonify(ok=False, msg='سجّل دخول أولاً'), 401
    try:
        data = freq.get_json(force=True, silent=True) or {}
        stars = int(data.get('stars', 0))
        text = (data.get('text', '') or '').strip()
        if stars < 1 or stars > 5: return jsonify(ok=False, msg='اختر عدد النجوم')
        if len(text) < 5: return jsonify(ok=False, msg='اكتب تعليق أطول')
        if len(text) > 300: text = text[:300]
        conn = get_db()
        today_start = int(time.strftime('%s', time.gmtime(time.mktime(time.strptime(time.strftime('%Y-%m-%d'), '%Y-%m-%d')))))
        count = conn.execute('SELECT COUNT(*) as c FROM reviews WHERE user_id=? AND created_at>=?', (session['user_id'], today_start)).fetchone()
        if count and count['c'] >= 5:
            conn.close()
            return jsonify(ok=False, msg='وصلت الحد الأقصى (5 تقييمات باليوم)')
        uname = session.get('user_name', 'مستخدم')
        first_name = uname.split()[0] if uname else 'مستخدم'
        conn.execute('INSERT INTO reviews(user_id,user_name,stars,text,approved) VALUES(?,?,?,?,?)',
                     (session['user_id'], first_name, stars, text, 1))
        conn.commit()
        conn.close()
        return jsonify(ok=True, msg='شكراً لتقييمك!')
    except Exception as e:
        return jsonify(ok=False, msg='حدث خطأ: ' + str(e))

