@app.route('/api/admin/providers/update', methods=['POST'])
def api_admin_providers_update():
    if 'user_id' not in session or not session.get('is_admin'): return jsonify(ok=False), 403
    data = freq.get_json(force=True, silent=True) or {}
    pid = int(data.get('id', 0))
    if not pid: return jsonify(ok=False, msg='مزود غير صالح')
    conn = get_db()
    sets = []
    vals = []
    for k in ['name', 'api_url', 'api_key']:
        if k in data:
            sets.append(f'{k}=?')
            vals.append(data[k])
    if 'active' in data:
        sets.append('active=?')
        vals.append(1 if data['active'] else 0)
    if 'show_in_store' in data:
        sets.append('show_in_store=?')
        vals.append(1 if data['show_in_store'] else 0)
    if 'is_default' in data and data['is_default']:
        conn.execute('UPDATE providers SET is_default=0')
        sets.append('is_default=1')
        # المزود الرئيسي يعرض خدماته تلقائياً
        if 'show_in_store' not in data:
            sets.append('show_in_store=1')
    if sets:
        vals.append(pid)
        conn.execute(f"UPDATE providers SET {','.join(sets)} WHERE id=?", vals)
    conn.commit(); conn.close()
    if 'show_in_store' in data or 'active' in data or ('is_default' in data and data['is_default']):
        _all_services_cache['data'] = None
        _all_services_cache['time'] = 0
        _services_cache['data'] = None
        _services_cache['time'] = 0
        _bump_svc_version_only()
    return jsonify(ok=True, msg='تم التحديث')

@app.route('/api/admin/providers/delete', methods=['POST'])
def api_admin_providers_delete():
    if 'user_id' not in session or not session.get('is_admin'): return jsonify(ok=False), 403
    data = freq.get_json(force=True, silent=True) or {}
    pid = int(data.get('id', 0))
    conn = get_db()
    cnt = conn.execute('SELECT COUNT(*) as c FROM providers').fetchone()['c']
    if cnt <= 1:
        conn.close()
        return jsonify(ok=False, msg='لا يمكن حذف المزود الوحيد')
    conn.execute('DELETE FROM providers WHERE id=?', (pid,))
    try:
        conn.execute('DELETE FROM service_filters WHERE prov_id=?', (pid,))
    except: pass
    has_default = conn.execute('SELECT COUNT(*) as c FROM providers WHERE is_default=1').fetchone()['c']
    if not has_default:
        first = conn.execute('SELECT id FROM providers LIMIT 1').fetchone()
        if first: conn.execute('UPDATE providers SET is_default=1 WHERE id=?', (first['id'],))
    conn.commit(); conn.close()
    _all_services_cache['data'] = None
    _all_services_cache['time'] = 0
    _services_cache['data'] = None
    _services_cache['time'] = 0
    _bump_svc_version_only()
    return jsonify(ok=True, msg='تم الحذف')

