@app.route('/api/generate-key', methods=['POST'])
def api_generate_key():
    if 'user_id' not in session:
        return jsonify(ok=False), 401
    new_key = 'fc_' + secrets.token_hex(20)
    conn = get_db()
    conn.execute('UPDATE users SET api_key=? WHERE id=?', (new_key, session['user_id']))
    conn.commit()
    conn.close()
    return jsonify(ok=True, key=new_key)

@app.route('/api/get-key')
def api_get_key():
    if 'user_id' not in session:
        return jsonify(ok=False), 401
    conn = get_db()
    user = conn.execute('SELECT api_key FROM users WHERE id=?', (session['user_id'],)).fetchone()
    conn.close()
    return jsonify(ok=True, key=user['api_key'] if user else '')

@app.route('/api/v2', methods=['GET', 'POST'])
def api_v2_smm():
    data = {}
    try:
        for k, v in freq.args.items(): data[k] = v
    except: pass
    try:
        for k, v in freq.form.items(): data[k] = v
    except: pass
    try:
        if freq.is_json and freq.json:
            for k, v in freq.json.items(): data[k] = v
    except: pass
    key = data.get('key', '')
    action = data.get('action', '')
    if not key:
        return jsonify(error='invalid_api_key'), 401
    conn = get_db()
    user = conn.execute('SELECT * FROM users WHERE api_key=? AND banned=0', (key,)).fetchone()
    conn.close()
    if not user:
        return jsonify(error='invalid_api_key'), 401
    uid = user['id']
    bal = float(user['balance'])
    if action == 'services':
        svcs = get_smm_services()
        conn2 = get_db()
        frows = conn2.execute('SELECT * FROM service_filters').fetchall()
        conn2.close()
        hidden_svcs, hidden_plats, cat_profits = set(), set(), {}
        for f in frows:
            ft, fk, fp = f['filter_type'], str(f['filter_key']), f['platform']
            if f['hidden']:
                if ft == 'service': hidden_svcs.add(fk)
                elif ft == 'platform': hidden_plats.add(fk)
            if ft == 'category' and f['profit_pct'] is not None:
                cat_profits[fp + '|||' + fk] = f['profit_pct']
        result = []
        for s in svcs:
            cat, name, sid = s.get('category',''), s.get('name',''), str(s.get('service',''))
            rate = float(s.get('rate','0') or 0)
            platform = _detect_platform(cat, name)
            if platform in hidden_plats or sid in hidden_svcs: continue
            ck = platform + '|||' + cat
            if ck in cat_profits and cat_profits[ck] > 0:
                rate = round(rate * (1 + cat_profits[ck] / 100.0), 4)
            result.append({'service': sid, 'name': name, 'category': cat, 'rate': str(rate), 'min': str(s.get('min','0')), 'max': str(s.get('max','0'))})
        return jsonify(result)
    elif action == 'add':
        sid, link = str(data.get('service','')), str(data.get('link','')).strip()
        try: qty = int(data.get('quantity', 0))
        except: return jsonify(error='invalid_quantity'), 400
        if not sid or not link or not qty: return jsonify(error='missing_params'), 400
        svcs = get_all_smm_services()
        svc = None
        for s in svcs:
            if str(s.get('service','')) == sid: svc = s; break
        if not svc: return jsonify(error='service_not_found'), 400
        mn, mx = int(svc.get('min',0)), int(svc.get('max',0))
        if qty < mn or qty > mx: return jsonify(error='quantity_out_of_range', min=mn, max=mx), 400
        rate = float(svc.get('rate','0') or 0)
        cat = svc.get('category','')
        platform = _detect_platform(cat, svc.get('name',''))
        conn2 = get_db()
        for f in conn2.execute("SELECT * FROM service_filters WHERE filter_type='category' AND filter_key=? AND platform=?", (cat, platform)).fetchall():
            if f['profit_pct'] is not None and f['profit_pct'] > 0:
                rate = round(rate * (1 + f['profit_pct'] / 100.0), 4)
        conn2.close()
        cost = round((rate * qty) / 1000.0, 4)
        if not user['is_admin'] and bal < cost:
            return jsonify(error='insufficient_balance', balance=round(bal,4), cost=cost), 400
        try:
            _api_url, _api_key, _prov_id = _find_service_provider(sid)
            r = requests.post(_api_url, data={'key': _api_key, 'action': 'add', 'service': svc['service'], 'link': link, 'quantity': qty}, timeout=15)
            rec = r.json()
            if 'order' not in rec: return jsonify(error='provider_error'), 500
            _rf = str(svc.get('refill',''))
            if _rf in ('0','False','false'): _rf = ''
            conn3 = get_db()
            if not user['is_admin']:
                conn3.execute('UPDATE users SET balance=balance-? WHERE id=?', (cost, uid))
            _did = _next_display_id()
            conn3.execute('INSERT INTO orders(user_id,order_id,service,service_name,link,quantity,charge,site_charge,status,refill_days,display_id,provider_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)',
                         (uid, str(rec['order']), sid, svc.get('name',''), link, qty, str(rec.get('charge',0)), cost, 'Processing', _rf, _did, _prov_id))
            conn3.commit()
            new_bal = conn3.execute('SELECT balance FROM users WHERE id=?', (uid,)).fetchone()['balance']
            conn3.close()
            return jsonify(order=_did, cost=cost, balance=round(new_bal,4))
        except Exception as e:
            return jsonify(error=str(e)), 500
    elif action == 'status':
        oid = str(data.get('order',''))
        if not oid: return jsonify(error='missing_order_id'), 400
        try:
            _conn = get_db()
            _orow = _conn.execute('SELECT order_id, provider_id FROM orders WHERE display_id=? AND user_id=?', (oid, uid)).fetchone()
            if not _orow:
                _orow = _conn.execute('SELECT order_id, provider_id FROM orders WHERE order_id=? AND user_id=?', (oid, uid)).fetchone()
            _conn.close()
            _poid = _orow['order_id'] if _orow and _orow['order_id'] else oid
            _ord_pid = 0
            try:
                if _orow: _ord_pid = int(_orow['provider_id'] or 0)
            except: _ord_pid = 0
            if _ord_pid:
                _api_url2, _api_key2, _prov_id2 = get_provider_api(_ord_pid)
            else:
                _api_url2, _api_key2, _prov_id2 = get_provider_api()
            r = requests.post(_api_url2, data={'key': _api_key2, 'action': 'status', 'order': _poid}, timeout=15)
            return jsonify(r.json())
        except:
            return jsonify(error='status_unavailable'), 500
    elif action == 'balance':
        return jsonify(balance=str(round(bal,4)), currency='USD')
    else:
        return jsonify(error='invalid_action', available=['services','add','status','balance']), 400

@app.route('/order/<platform>')
def order_page(platform):
    if 'user_id' not in session:
        return redirect('/')
    platform = platform.replace('%20',' ')
    return ORDER_PAGE_HTML.replace('__PLATFORM__', platform).replace('__SITE_NAME__', get_setting('site_name', 'fastcrand'))

