QUEUED_CHECK_INTERVAL = 30

def _bg_process_queued():
    """معالج الطلبات المعلّقة — يحاول إرسالها للمزود لما يصير عنده رصيد"""
    time.sleep(15)
    print('[QUEUE] Queued orders processor started (30s interval)')
    while True:
        try:
            conn = get_db()
            try:
                queued = conn.execute("SELECT * FROM orders WHERE status='Queued' AND (order_id IS NULL OR order_id='') ORDER BY id ASC").fetchall()
            finally:
                conn.close()
            if not queued:
                time.sleep(QUEUED_CHECK_INTERVAL)
                continue
            print(f'[QUEUE] Found {len(queued)} queued order(s) to retry')
            # كاش رصيد لكل مزود (يُعاد تعبئته كل دورة)
            _prov_bal_cache = {}
            def _bal_for(pid):
                if pid in _prov_bal_cache: return _prov_bal_cache[pid]
                try:
                    if pid:
                        u,k,_ = get_provider_api(pid)
                    else:
                        u,k,_ = get_provider_api()
                    br = requests.post(u, data={'key': k, 'action': 'balance'}, timeout=10)
                    bd = br.json()
                    raw = bd.get('balance', 0)
                    if isinstance(raw, str):
                        raw = raw.replace(',', '').strip()
                    v = float(raw)
                    print(f'[QUEUE] Provider {pid} balance: ${v:.4f}')
                except Exception as e:
                    print(f'[QUEUE] Failed balance check for provider {pid}: {e}')
                    # -1 = فشل الفحص، نتجاوز هذه الدورة (مو نخسر الطلب)
                    v = -1.0
                _prov_bal_cache[pid] = v
                return v
            for order in queued:
                try:
                    _ord_pid = 0
                    try: _ord_pid = int(order['provider_id'] or 0)
                    except: _ord_pid = 0
                    cur_bal = _bal_for(_ord_pid)
                    # -1 = فشل فحص الرصيد، نعيد المحاولة بالدورة الجاية
                    if cur_bal < 0:
                        continue
                    if cur_bal <= 0:
                        continue
                    if _ord_pid:
                        _api_url, _api_key, _prov_id = get_provider_api(_ord_pid)
                    else:
                        _api_url, _api_key, _prov_id = get_provider_api()
                    # بناء payload — مع comments إذا موجود
                    _payload = {
                        'key': _api_key, 'action': 'add',
                        'service': order['service'], 'link': order['link'], 'quantity': int(order['quantity'])
                    }
                    try:
                        _cmts = order['comments'] if 'comments' in order.keys() else ''
                        if _cmts:
                            _payload['comments'] = _cmts
                    except: pass
                    print(f"[QUEUE] Sending order #{order['display_id']} to provider {_ord_pid}...")
                    r = requests.post(_api_url, data=_payload, timeout=15)
                    result = r.json()
                    if 'order' in result and result['order']:
                        provider_charge = float(result.get('charge', 0))
                        _prov_bal_cache[_ord_pid] = max(0, cur_bal - provider_charge)
                        conn2 = get_db()
                        try:
                            conn2.execute('UPDATE orders SET order_id=?, status=?, charge=? WHERE id=?',
                                         (str(result['order']), 'Processing', str(provider_charge), order['id']))
                            conn2.commit()
                        finally:
                            conn2.close()
                        push_user_notif(order['user_id'], 'order', f'تم إرسال طلبك #{order["display_id"]}', f'{order["service_name"]} — تم الإرسال تلقائياً', 'check', goto=f'order:{order["display_id"]}')
                        try: _add_referral_commission(order['user_id'], str(result['order']), provider_charge)
                        except: pass
                        print(f"[QUEUE] OK Order #{order['display_id']} sent successfully (provider order: {result['order']})")
                    else:
                        err = str(result.get('error', '')).lower()
                        print(f"[QUEUE] FAIL Order #{order['display_id']} failed: {err}")
                        # رصيد غير كافي → نوقف بقية الطلبات لهذا المزود بهذه الدورة
                        if 'balance' in err or 'fund' in err or 'insufficient' in err:
                            _prov_bal_cache[_ord_pid] = 0
                        # خدمة محذوفة → نلغي الطلب ونرجّع الفلوس
                        elif any(kw in err for kw in [
                            'invalid service', 'service not found', 'not found',
                            'does not exist', 'service is not', 'incorrect service',
                            'service unavailable', 'service was removed',
                            'service deleted', 'invalid service id', 'bad service'
                        ]):
                            conn3 = get_db()
                            try:
                                site_charge = float(order['site_charge'] or 0)
                                if site_charge > 0:
                                    conn3.execute('UPDATE users SET balance=balance+? WHERE id=?',
                                                 (site_charge, order['user_id']))
                                conn3.execute("UPDATE orders SET status='Canceled', refunded=1 WHERE id=?",
                                             (order['id'],))
                                conn3.commit()
                            finally:
                                conn3.close()
                            push_user_notif(order['user_id'], 'system',
                                          f'تم إلغاء طلبك #{order["display_id"]}',
                                          f'الخدمة لم تعد متوفرة — تم إرجاع ${order["site_charge"]} لرصيدك',
                                          'wallet', goto='wallet:')
                            print(f"[QUEUE] CANCEL Order #{order['display_id']} cancelled (service dead) — refunded")
                        # أي خطأ ثاني — عداد محاولات: بعد 10 يصير Error
                        else:
                            try:
                                conn4 = get_db()
                                try:
                                    cur_attempts = 0
                                    try: cur_attempts = int(order['refill_count'] or 0)
                                    except: cur_attempts = 0
                                    new_attempts = cur_attempts + 1
                                    if new_attempts >= 10:
                                        conn4.execute("UPDATE orders SET status='Error' WHERE id=?",
                                                     (order['id'],))
                                        push_user_notif(order['user_id'], 'system',
                                                      f'فشل طلب #{order["display_id"]}',
                                                      f'تواصل مع الدعم — {err[:60]}',
                                                      'warning')
                                        print(f"[QUEUE] WARN Order #{order['display_id']} marked as Error after 10 retries")
                                    else:
                                        conn4.execute("UPDATE orders SET refill_count=? WHERE id=?",
                                                     (new_attempts, order['id']))
                                    conn4.commit()
                                finally:
                                    conn4.close()
                            except: pass
                except Exception as e:
                    print(f"[QUEUE] Exception while processing order: {e}")
                time.sleep(1)
        except Exception as e:
            print(f"[QUEUE] Outer loop exception: {e}")
        time.sleep(QUEUED_CHECK_INTERVAL)

import threading

def _bg_check_orders():
    pass
    while True:
        time.sleep(300)
        try:
            conn = get_db()
            try:
                active = conn.execute("SELECT * FROM orders WHERE status IN ('Processing','Pending','In progress') AND refunded=0").fetchall()
            finally:
                conn.close()
            for order in active:
                try:
                    _ord_pid = 0
                    try: _ord_pid = int(order['provider_id'] or 0)
                    except: _ord_pid = 0
                    if _ord_pid:
                        _bg_api_url, _bg_api_key, _bg_prov_id = get_provider_api(_ord_pid)
                    else:
                        _bg_api_url, _bg_api_key, _bg_prov_id = get_provider_api()
                    r = requests.post(_bg_api_url, data={
                        'key': _bg_api_key, 'action': 'status', 'order': order['order_id']
                    }, timeout=15)
                    result = r.json()
                    new_status = result.get('status', '')
                    if not new_status or new_status == order['status']:
                        continue
                    conn2 = get_db()
                    try:
                        conn2.execute('UPDATE orders SET status=?, charge=? WHERE id=?',
                                     (new_status, result.get('charge', '0'), order['id']))
                        uid = order['user_id']
                        site_charge = float(order['site_charge'] or 0)
                        qty = int(order['quantity'] or 0)
                        remains = int(result.get('remains', 0))
                        oid = order['order_id']
                        if new_status == 'Canceled' and site_charge > 0 and not order['refunded']:
                            conn2.execute('UPDATE users SET balance=balance+? WHERE id=?', (site_charge, uid))
                            conn2.execute('UPDATE orders SET refunded=1 WHERE id=?', (order['id'],))
                            push_user_notif(uid, 'system', f'استرجاع ${site_charge:.2f}', f'طلب #{oid} تم إلغاؤه تلقائياً — تم إرجاع المبلغ', 'wallet', goto='wallet:')
                        elif new_status == 'Partial' and site_charge > 0 and qty > 0 and remains > 0 and not order['refunded']:
                            refund = round(site_charge * (remains / qty), 2)
                            if refund > 0:
                                conn2.execute('UPDATE users SET balance=balance+? WHERE id=?', (refund, uid))
                                conn2.execute('UPDATE orders SET refunded=1 WHERE id=?', (order['id'],))
                                push_user_notif(uid, 'system', f'استرجاع جزئي ${refund:.2f}', f'طلب #{oid} جزئي — تم إرجاع المتبقي', 'wallet')
                        elif new_status == 'Completed' and order['status'] != 'Completed':
                            push_user_notif(uid, 'order', f'طلب #{oid} اكتمل ', f'{order["service_name"]}', 'done', goto=f'order:{oid}')
                        conn2.commit()
                    finally:
                        conn2.close()
                except Exception as e:
                    pass
        except Exception as e:
            pass

def _bg_sync_prices():
    pass
    time.sleep(30)
    while True:
        try:
            api_url, api_key, _pid = get_provider_api()
            if api_url and api_key:
                r = requests.post(api_url, data={'key': api_key, 'action': 'services'}, timeout=15)
                data = r.json()
                if isinstance(data, list) and len(data) > 0:
                    _services_cache['data'] = data
                    _services_cache['time'] = time.time()
                    _save_services_to_file(data)
        except Exception as e:
            pass
        time.sleep(180)

def _bg_cleanup_images():
    pass
    time.sleep(120)
    while True:
        try:
            cutoff = time.time() - (48 * 3600)
            cleaned = 0
            for folder in [TK_IMG_DIR, VOICE_DIR]:
                if not os.path.isdir(folder):
                    continue
                for fname in os.listdir(folder):
                    fpath = os.path.join(folder, fname)
                    try:
                        if os.path.isfile(fpath) and os.path.getmtime(fpath) < cutoff:
                            os.remove(fpath)
                            cleaned += 1
                    except: pass
            if cleaned > 0:
                pass
        except Exception as e:
            pass
        time.sleep(3600)

def _gc_cleanup():
    while True:
        time.sleep(1800)
        gc.collect()

def _health_watchdog():
    pass
    import urllib.request, ssl
    time.sleep(30)
    _fail_count = 0
    _ctx = ssl.create_default_context()
    _ctx.check_hostname = False
    _ctx.verify_mode = ssl.CERT_NONE
    while True:
        time.sleep(60)
        try:
            req = urllib.request.Request('https://127.0.0.1:443/', method='HEAD')
            urllib.request.urlopen(req, timeout=10, context=_ctx)
            _fail_count = 0
        except Exception:
            _fail_count += 1
            if _fail_count >= 3:
                print('[WATCHDOG] Server unresponsive! Killing process...')
                os._exit(1)

