    def _http_redirect():
        from flask import Flask as F2
        redir = F2('redirect')
        @redir.route('/', defaults={'path': ''})
        @redir.route('/<path:path>')
        def _redir(path):
            from flask import request as rq
            return redirect('https://' + rq.host.split(':')[0] + '/' + path, code=301)
        try:
            redir.run(host='0.0.0.0', port=80, debug=False)
        except Exception as e:
            pass

    http_thread = threading.Thread(target=_http_redirect, daemon=True)
    http_thread.start()

